const BIST_2026_CLOSED=new Set(['2026-01-01','2026-03-20','2026-03-21','2026-03-22','2026-04-23','2026-05-01','2026-05-19','2026-05-27','2026-05-28','2026-05-29','2026-05-30','2026-07-15','2026-08-30','2026-10-29']);

const BIST_2026_HALF=new Set(['2026-03-19','2026-05-26','2026-10-28']);

function calendarOverrides(){try{return JSON.parse(state.settings?.calendarOverridesJson||'[]')}catch{return []}}

function bistCalendarStatus(date){const d=parseDate(date);if(!d)return 'CLOSED';const day=d.getUTCDay();if(day===0||day===6)return 'CLOSED';const override=calendarOverrides().find(x=>ymd(x.date)===ymd(date));if(override?.status)return override.status;if(BIST_2026_CLOSED.has(ymd(date)))return 'CLOSED';if(BIST_2026_HALF.has(ymd(date)))return 'HALF_DAY';return 'OPEN';}

function publicRunSettings(x){const allow=['monthsBack','commissionBps','slippageBps','maxParticipationPct','assumedPositionTRY','minTurnoverM','minPrice','maxDailyMovePct','qualityMin','targetReturnPct','targetTopN','learningHalfLifeDays','behaviorLookbackDays','genomeLookbackDays','modelVersion'];return Object.fromEntries(allow.filter(k=>k in (x||{})).map(k=>[k,x[k]]));}

function deepSecretSanitize(value){const secret=/token|api[_-]?key|authorization|secret|password|cookie|credential|bearer|keystore|private[_-]?key|signing[_-]?key|session[_-]?id/i;if(Array.isArray(value))return value.map(deepSecretSanitize);if(value&&typeof value==='object'){const o={};for(const [k,v] of Object.entries(value))if(!secret.test(k))o[k]=deepSecretSanitize(v);return o;}return value;}

const IMPOSSIBLE_RETURN_FIELDS=new Set(['signalDayReturn','dayReturn','maxNetReturn','closeNetReturn','netReturn','grossReturn','currentReturn','maxPotential','ret']);
function sanitizeRunReturnNode(value,path,issues){
  if(Array.isArray(value))return value.map((x,i)=>sanitizeRunReturnNode(x,`${path}[${i}]`,issues));
  if(value&&typeof value==='object'){
    const out={};
    for(const [k,v] of Object.entries(value)){
      const n=(v===null||v===undefined||v===''?null:Number(v));
      if(IMPOSSIBLE_RETURN_FIELDS.has(k)&&Number.isFinite(n)&&n<=-99.5){issues.push(`${path}.${k}`);out[k]=null;continue;}
      out[k]=sanitizeRunReturnNode(v,`${path}.${k}`,issues);
    }
    return out;
  }
  return value;
}
function sanitizeStoredRun(run){
  const clean=deepSecretSanitize({...run});clean.settings=publicRunSettings(run?.settings||{});
  const issues=[];
  for(const key of ['selection','entryUniverse','predictionUniverse','criteria','actualDual'])if(key in clean)clean[key]=sanitizeRunReturnNode(clean[key],key,issues);
  if(issues.length){clean.obsolete=true;clean.learningEligible=false;clean.integrityRejected='IMPOSSIBLE_MINUS100_RETURN';clean.integrityRejectedFields=[...new Set(issues)].slice(0,160);clean.integrityRejectedAt=clean.integrityRejectedAt||new Date().toISOString();}
  return clean;
}

function stableHash(s){let h=2166136261;for(let i=0;i<s.length;i++){h^=s.charCodeAt(i);h=Math.imul(h,16777619);}return (`00000000${(h>>>0).toString(16)}`).slice(-8);}

async function sha256Hex(s){const data=new TextEncoder().encode(s),hash=await crypto.subtle.digest('SHA-256',data);return [...new Uint8Array(hash)].map(x=>x.toString(16).padStart(2,'0')).join('');}

function isTruthEligible(r){return r?.calculationEligible!==false&&!!r?.sym&&Array.isArray(r.series?.date)&&r.series.date.length>=3&&Number.isFinite(r.series?.calcClose?.at(-1)??r.series?.close?.at(-1));}

function hardSafetyFilter(r){const reasons=[];if(!isTruthEligible(r))reasons.push('Sonuç serisi yok');if(!Number.isFinite(r.price)||!Number.isFinite(r.high)||!Number.isFinite(r.low)||r.low>r.high)reasons.push('OHLC bütünlüğü');if(tradingDaysOld(r.latestDate)>3)reasons.push('Eski veri');if((r.quality||0)<25)reasons.push('Çok düşük kalite');if((r.sourceConflicts?.length||0)>20)reasons.push('Aşırı kaynak uyuşmazlığı');return {pass:!reasons.length,reasons};}

function rebuildModelViews(records){const common=buildModels(records),hard=records.filter(r=>hardSafetyFilter(r).pass),discovery=buildModels(records,{pool:hard,weights:common.weights,calibrate:false});state.discoveryScores=discovery.scores;state.filterDiagnostics={total:records.length,hard:hard.length,common:common.eligible.length,eliminated:records.length-common.eligible.length,reasons:Object.fromEntries(records.map(r=>[r.sym,globalFilter(r).reasons]))};state.modelBySym=common.bySym||new Map();return common;}

function expectedHistoryBars(){
  return clamp(Math.round((Number(state.settings?.monthsBack)||14)*21*.80),120,2200);
}

function completionReport(bundle){
  const c=coverage(bundle||{bars:[],fundamentals:{},live:null}),target=expectedHistoryBars();
  const gaps=[];
  if(c.bars<target)gaps.push(`tarihsel bar ${c.bars}/${target}`);
  if(c.open<.85)gaps.push(`açılış kapsamı ${fmt(c.open*100,0)}%`);
  if(c.vol<.85)gaps.push(`hacim kapsamı ${fmt(c.vol*100,0)}%`);
  if(c.fund<4)gaps.push(`temel alan ${c.fund}/4`);
  if(state.settings?.liveEnabled&&!c.live)gaps.push('anlık fiyat');
  const score=100*(.38*clamp(c.bars/target,0,1)+.16*clamp(c.open/.85,0,1)+.16*clamp(c.vol/.85,0,1)+.15*clamp(c.fund/4,0,1)+.15*(state.settings?.liveEnabled?(c.live?1:0):1));
  return {...c,targetBars:target,gaps,complete:gaps.length===0,score:clamp(score,0,100)};
}

function recordCompletionReport(rec){
  if(!rec)return {complete:false,score:0,gaps:['kayıt yok'],bars:0,targetBars:expectedHistoryBars()};
  return completionReport(bundleFromRecord(rec));
}

function marketBucketInfo(){const now=trParts(),times=String(state.settings?.aiMarketTimeBuckets||state.settings?.autoSyncTimes||'08:20,12:20,18:20,21:30').split(/[;,\s]+/).filter(x=>/^([01]\d|2[0-3]):[0-5]\d$/.test(x)).sort(),minute=now.hour*60+now.minute;let bucket=times.filter(x=>{const [h,m]=x.split(':').map(Number);return h*60+m<=minute;}).at(-1);let date=now.date;if(!bucket){bucket=times.at(-1)||'21:30';const d=new Date(Date.now()-DAY);date=new Intl.DateTimeFormat('en-CA',{timeZone:'Europe/Istanbul',year:'numeric',month:'2-digit',day:'2-digit'}).format(d);}return {date,bucket,key:`${date}|${bucket}`};}

function currentMarketEvidence(){const b=marketBucketInfo(),rows=state.records.slice().sort((a,c)=>a.sym.localeCompare(c.sym)),latestDate=rows.map(x=>x.latestDate).filter(Boolean).sort().at(-1)||null,payload=rows.map(x=>[x.sym,x.latestDate,Number.isFinite(x.livePrice)?Number(x.livePrice).toFixed(4):'',x.apiAccessedAt||'',x.series?.close?.at(-1),x.series?.volume?.at(-1)]).join('|');return {bucketKey:b.key,bucket:b.bucket,marketDate:b.date,latestDate,recordCount:rows.length,fingerprint:stableHash(`${latestDate}|${payload}`),generatedAt:nowISO()};}

async function reserveAICall(kind,manual){const evidence=currentMarketEvidence();if(!evidence.recordCount)throw new Error('Ücretli AI işlemi için doğrulanmış piyasa verisi yok');if(state.settings.aiRequireNewMarketBucket!==false){const last=state.aiPaidEvidence||{};if(last.fingerprint===evidence.fingerprint||last.bucketKey===evidence.bucketKey)throw new Error(`Yeni piyasa zaman dilimi ve yeni veri yok; AI çağrısı engellendi (${evidence.bucketKey})`);}const day=trParts().date,key=`${day}`,usage=state.usage[key]||{count:0,kinds:[]},limit=Number(state.settings.aiDailyCallLimit||2);if(limit>=0&&usage.count>=limit)throw new Error(`Günlük AI çağrı sınırı doldu (${limit})`);if(manual&&state.settings.aiRequireManualPaidCall&&!confirm(`${kind==='DAILY_AUDIT'?'Günlük denetim':'Aday üretimi'} yeni bir OpenAI isteği ve maliyet oluşturabilir. Devam edilsin mi?`))throw new Error('AI isteği kullanıcı tarafından iptal edildi');usage.count++;usage.kinds.push({kind,at:nowISO(),evidence});state.usage={[key]:usage};state.aiPaidEvidence={...evidence,kind,reservedAt:nowISO(),status:'RESERVED'};await dbPut('meta',{key:'aiUsage',value:state.usage,updatedAt:nowISO()});await dbPut('meta',{key:'aiPaidEvidence',value:state.aiPaidEvidence,updatedAt:nowISO()});return evidence;}

async function markAIEvidenceResult(status,extra={}){if(!state.aiPaidEvidence)return;state.aiPaidEvidence={...state.aiPaidEvidence,status,completedAt:nowISO(),...extra};await dbPut('meta',{key:'aiPaidEvidence',value:state.aiPaidEvidence,updatedAt:nowISO()});}

