function trParts(v=new Date()){const parts=new Intl.DateTimeFormat('en-CA',{timeZone:'Europe/Istanbul',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hourCycle:'h23',weekday:'short'}).formatToParts(parseDate(v)||new Date());const o={};for(const x of parts)o[x.type]=x.value;return {date:`${o.year}-${o.month}-${o.day}`,hour:Number(o.hour),minute:Number(o.minute),weekday:o.weekday};}

function marketContext(at=new Date(),latestTradingDate=null){
  const t=trParts(at),date=t.date,mins=t.hour*60+t.minute,status=bistCalendarStatus(date);
  let window='CLOSED',entryMode='NEXT_OPEN';
  if(status==='CLOSED')window='HOLIDAY';
  else if(mins<600)window='PREOPEN';
  else if(mins<(status==='HALF_DAY'?780:1080)){window='LIVE';entryMode='LIVE';}
  else window='AFTER_CLOSE';
  return {window,entryMode,date,latestTradingDate,status};
}

function bandValue(v,lo,hi,outerLo,outerHi){if(!Number.isFinite(v))return null;if(v>=lo&&v<=hi)return 1;if(v<lo)return clamp((v-outerLo)/(lo-outerLo),0,1);return clamp((outerHi-v)/(outerHi-hi),0,1);}

function safeRatio(a,b){return Number.isFinite(a)&&Number.isFinite(b)&&b!==0?a/b:null;}

function weightedDecayMean(rows,valueKey,weightKey='weight'){let n=0,d=0;for(const r of rows){const v=r[valueKey],w=r[weightKey]??1;if(Number.isFinite(v)&&Number.isFinite(w)){n+=v*w;d+=w}}return d?n/d:null;}

