function metric(label,value,sub='',cls=''){return `<div class="card metric"><div class="label">${html(label)}</div><div class="value ${cls}">${html(value)}</div><div class="sub">${html(sub)}</div></div>`}

function latestTargetRun(){return state.runs.find(x=>x.evaluated&&x.targetDefinition===TARGET_DEFINITION);}

function openAIKeyModule(){
  const configured=!!globalThis.AurumNativeAI?.configured?.(),health=state.ai.health,status=health?.ok?'BAĞLANTI DOĞRULANDI':configured?'ANAHTAR KAYITLI':'ANAHTAR YOK',statusClass=health?.ok?'ok':configured?'warn':'bad',checked=health?.checkedAt?new Date(health.checkedAt).toLocaleString('tr-TR'):'Henüz bağlantı testi yapılmadı';
  return `<div class="section-head"><div class="section-title"><h2>OpenAI API Anahtarı</h2></div><small>Bağımsız Ayar Modülü</small></div><div class="card gold-edge api-key-module"><div class="list-row"><div><strong>OpenAI bağlantı anahtarı</strong><small>AI denetimi ve aday model işlemleri için kullanılır.</small></div><span class="badge ${statusClass}">${status}</span></div><div class="field aurum-api-key-field" style="margin-top:12px"><label>API anahtarı</label><div class="api-key-input-row"><input id="generalOpenaiApiKey" class="aurum-api-key-input" type="password" value="" placeholder="sk-proj-…" autocomplete="off" autocapitalize="off" autocorrect="off" spellcheck="false" inputmode="text" enterkeyhint="done" onclick="this.focus()" onpointerdown="event.stopPropagation()" ontouchstart="event.stopPropagation()"><button id="generalOpenaiKeyToggle" class="ghost-btn compact-btn" type="button" onclick="toggleGeneralOpenAIKey()">Göster</button></div><div class="actions" style="margin-top:6px"><button class="ghost-btn compact-btn" type="button" onclick="if(!globalThis.AurumNativeAI?.openEditor?.())showAurumNotice('Android güvenli giriş penceresi açılamadı','error',3000)">Android güvenli giriş</button></div><small>Anahtar yalnız Android Keystore ve OpenAI isteklerinde kullanılır; dışa aktarımlara ve işlem günlüklerine eklenmez.</small></div><div class="actions" style="margin-top:12px"><button class="gold-btn" onclick="saveGeneralOpenAIKey()" ${state.ai.busy?'disabled':''}>Anahtarı Kaydet</button><button class="ghost-btn" onclick="testGeneralOpenAIKey()" ${state.ai.busy?'disabled':''}>Bağlantıyı Test Et</button><button class="danger-btn" onclick="deleteGeneralOpenAIKey()" ${!configured||state.ai.busy?'disabled':''}>Anahtarı Sil</button><button class="ghost-btn" onclick="goPage('ai')">AI Ayarlarını Aç</button></div><p class="muted api-key-status">Son doğrulama: ${html(checked)}</p>${state.ai.lastError?`<p class="error-text">${html(state.ai.lastError)}</p>`:''}</div>`;
}

window.toggleGeneralOpenAIKey=()=>{const input=$('#generalOpenaiApiKey'),btn=$('#generalOpenaiKeyToggle');if(!input)return;const visible=input.type==='text';input.type=visible?'password':'text';if(btn)btn.textContent=visible?'Göster':'Gizle';};

window.saveGeneralOpenAIKey=async()=>{try{const input=$('#generalOpenaiApiKey'),key=normalizeOpenAIKey(input?.value);if(!key)throw new Error('Geçerli bir OpenAI API anahtarı girin');if(!globalThis.AurumNativeAI?.save?.(key))throw new Error('API anahtarı Android güvenli alanına kaydedilemedi');state.settings.openaiApiKey='';state.settings.aiEnabled=true;state.settings.settingsSchemaVersion=SETTINGS_SCHEMA_VERSION;state.ai.health=null;state.ai.lastError=null;await saveSettings();await log('ok','OpenAI API anahtarı Genel modülünden kaydedildi',{configured:true});render();showAurumNotice('OpenAI API anahtarı kaydedildi');}catch(e){state.ai.lastError=e.message;await log('error','OpenAI API anahtarı kaydedilemedi',{error:e.message});render();showAurumNotice(e.message||'API anahtarı kaydedilemedi','error',3200);}};

window.testGeneralOpenAIKey=async()=>{try{const input=$('#generalOpenaiApiKey'),key=normalizeOpenAIKey(input?.value);if(!key)throw new Error('Önce geçerli bir OpenAI API anahtarı girin');if(!globalThis.AurumNativeAI?.save?.(key))throw new Error('API anahtarı Android güvenli alanına kaydedilemedi');state.settings.openaiApiKey='';state.settings.aiEnabled=true;await saveSettings();await aiCheckHealth();}catch(e){state.ai.lastError=e.message;render();showAurumNotice(e.message||'OpenAI bağlantısı doğrulanamadı','error',3600);}};

window.deleteGeneralOpenAIKey=async()=>{if(!confirm('Kayıtlı OpenAI API anahtarı silinsin mi?'))return;globalThis.AurumNativeAI?.remove?.();state.settings.openaiApiKey='';state.settings.aiEnabled=false;state.ai.health=null;state.ai.lastError=null;await saveSettings();await log('info','OpenAI API anahtarı kullanıcı tarafından silindi');render();showAurumNotice('OpenAI API anahtarı silindi');};

function morePage(){return `<div class="tabs"><button class="ghost-btn active" onclick="showSub('history',this)">Tarihsel Analiz</button><button class="ghost-btn" onclick="showSub('performance',this)">Performans</button><button class="ghost-btn" onclick="showSub('archive',this)">Arşiv</button><button class="ghost-btn" onclick="showSub('status',this)">Sistem Durumu</button><button class="ghost-btn" onclick="showSub('settings',this)">Ayarlar</button></div><div id="subContent">${historySub()}</div>`;}

function historySub(){const b=state.backtest;return `<div class="actions"><button class="gold-btn" onclick="runLocalBacktest()">Hedef Walk-forward Testi</button></div><div class="grid metrics" style="margin-top:12px">${metric('Test dönemi',b?.runs??'—','Günlük ankraj')}${metric('Hedef Precision@20',b?fmt(b.precisionDual20*100,1)+'%':'—','Top20 + ≥%5')}${metric('Hedef Recall@20',b?fmt(b.recallDual20*100,1)+'%':'—','Gerçek hedef kümesi')}${metric('Reel Top20',b?fmt(b.precisionTop20*100,1)+'%':'—','Tek başına')}${metric('≥%5',b?fmt(b.precisionFivePct*100,1)+'%':'—','Tek başına')}${metric('Ort. maksimum net',b?pct(b.avgMaxReturn):'—','İki seans')}${metric('NDCG@20',b?fmt(b.ndcg20,3):'—','Sıralama kalitesi')}</div><div class="card notice" style="margin-top:12px">${b?html(b.method):'Test henüz çalıştırılmadı.'} Sinyal kapanışta, giriş sonraki açılışta kabul edilir.</div>${b?.rows?.length?`<div class="table-wrap" style="margin-top:12px"><table><thead><tr><th>Tarih</th><th>Hedef</th><th>Recall</th><th>Top20</th><th>≥%5</th><th>Maks. Net</th><th>NDCG</th></tr></thead><tbody>${b.rows.map(x=>`<tr><td>${x.anchor}</td><td>${x.hits}/${x.selectedN||20} · ${fmt(x.precisionDual*100,1)}%</td><td>${fmt(x.recallDual*100,1)}%</td><td>${fmt(x.top20Precision*100,1)}%</td><td>${fmt(x.fivePrecision*100,1)}%</td><td>${pct(x.avgMaxReturn)}</td><td>${fmt(x.ndcg20,3)}</td></tr>`).join('')}</tbody></table></div>`:''}`;}

function performanceSub(){const ev=state.runs.filter(x=>x.evaluated&&x.targetDefinition===TARGET_DEFINITION),r=ev[0],a=performanceAggregate(),vd=state.performance.lastValidation||{},decision=state.performance.lastDecision||'BEKLEME';return `<div class="grid metrics">${metric('Tamamlanan hedef dönemi',ev.length,'Arşiv')}${metric('Son hedef isabeti',r?.metrics?.hitsDual??'—',r?.metrics?.selectedN?'/'+r.metrics.selectedN:'—')}${metric('Precision@20',a?fmt(a.precision*100,1)+'%':'—','İkili hedef')}${metric('Recall@20',a?fmt(a.recall*100,1)+'%':'—','Gerçek hedef kümesi')}${metric('Aynı gün isabet',a?fmt(a.sameDayPrecision*100,1)+'%':'—','Giriş seansı')}${metric('Ertesi gün isabet',a?fmt(a.nextDayPrecision*100,1)+'%':'—','Takip seansı')}${metric('Tabana karşı lift',a?fmt(a.dualLift,2)+'x':'—','Rastgele evren oranına göre')}${metric('Taban hedef oranı',a?fmt(a.baseDualRate*100,2)+'%':'—','Uygun evren')}${metric('Önceden Reel Top20',a?fmt(a.top20Precision*100,1)+'%':'—','Sinyal anında gerçekleşmemiş')}${metric('Dahilî Reel Top20',a?fmt(a.top20InclusivePrecision*100,1)+'%':'—','Takip edilenler dahil')}${metric('Takip başarısı dışlandı',a?fmt(a.avgChaseExcluded,1):'—','Dönem başına adet')}${metric('≥%5 hedefe temas',a?fmt(a.fivePrecision*100,1)+'%':'—','Ortalama')}${metric('MFE net potansiyel',a?pct(a.avgMax):'—','Ortalama')}${metric('Gerçekleşen kapanış net',a?pct(a.avgClose):'—','Ortalama')}${metric('Brier',a?fmt(a.brier,3):'—','Olasılık kalibrasyonu')}${metric('Maks. geri çekilme',a?pct(a.maxDrawdown):'—','Kapanış serisi')}${metric('Sharpe',a?fmt(a.sharpe,2):'—','Gerçek NAV yıllıklaştırılmış')}${metric('Yanlış pozitif',a?fmt(a.falsePositive*100,1)+'%':'—','İkili hedef')}</div><div class="section-head"><h2>İleri dönem ağırlık doğrulaması</h2></div><div class="card notice"><b class="${decision==='ONAYLANDI'?'validation-ok':decision==='REDDEDİLDİ'?'validation-bad':''}">${decision}</b> · Mevcut: ${fmt(vd.current?.score,2)} · Aday: ${fmt(vd.candidate?.score,2)} · Günlük azami değişim: ${fmt(state.settings.weightDailyCapPct,2)} puan. Aday, ayrılmış doğrulamada mevcut ağırlığı en az ${fmt(state.settings.promotionMargin,2)} puan geçmeden etkinleşmez.</div><div class="section-head"><h2>Otomatik ödül-ceza</h2></div><div class="card list">${MODEL_CRITERIA.map(k=>{const x=state.performance.raw?.[k]||{};return `<div class="list-row"><div><strong>${k} · ${CRITERION_CATALOG[k].name}</strong><small>${x.status||'ADAY'} · hedef ${fmt((x.dualPrecision||0)*100,1)}% · K_Tarihsel ${Number.isFinite(x.historicalHitPrecision)?fmt(x.historicalHitPrecision*20,2)+'/20':'—'} · S koltuk ${x.sSeats||0}${Number.isFinite(x.sSeatPrecision)?' · S başarı '+fmt(x.sSeatPrecision*100,1)+'%':''} · lift ${fmt(x.dualLift,2)}x · alt güven ${fmt((x.dualLowerBound||0)*100,1)}% · ${x.predictions||0} tahmin · ${x.independentPeriods||0} dönem</small></div><b>${fmt((state.performance.weights?.[k]??BASE_WEIGHTS[k])*100,2)}%</b></div>`}).join('')}</div>`;}

function archiveSub(){return `<div class="section-head"><h2>Model çalıştırmaları</h2></div><div class="card list">${state.runs.slice(0,80).map(x=>`<div class="list-row"><div><strong>${new Date(x.createdAt).toLocaleString('tr-TR')}</strong><small>${x.kind} · ${x.decisionWindow||'LEGACY'} · ${x.marketRegime||'—'} · ${x.modelVersion}</small></div><div style="text-align:right"><b>${x.selection.slice(0,3).map(y=>y.sym).join(' · ')}</b><small>${x.evaluated?(x.targetDefinition===TARGET_DEFINITION?`${x.metrics?.hitsDual??0}/${x.metrics?.selectedN||x.selection?.length||0} hedef · aynı ${x.metrics?.sameDayHits??0} · ertesi ${x.metrics?.nextDayHits??0} · dışlanan takip ${x.metrics?.chaseExcluded??0} · lift ${fmt(x.metrics?.dualLift,2)}x`:`LEGACY ${x.metrics?.hits??0}/20`):'BEKLİYOR'}</small></div></div>`).join('')||'<p class="muted">Arşiv boş.</p>'}</div><div class="section-head"><h2>Kapanan seçimler</h2></div><div class="card list">${(state.closedEntries||[]).slice(0,100).map(x=>{const start=x.entryTime||x.signalTime,startLabel=start?new Date(start).toLocaleString('tr-TR'):'—',pricePath=Number.isFinite(x.entryPrice)?`${fmt(x.entryPrice)} → ${fmt(x.exitPrice)}`:'İşlem açılmadı';return `<div class="list-row"><div><strong>${x.sym} · ${html(x.resultClass)}</strong><small>${startLabel} → ${new Date(x.exitTime).toLocaleString('tr-TR')} · ${pricePath}</small></div><b class="${(x.netReturn??0)>=0?'green':'red'}">${pct(x.netReturn)}</b></div>`}).join('')||'<p class="muted">Kapanan seçim yok.</p>'}</div>`;}

function statusSub(){return `<div class="grid metrics">${metric('Durum',state.syncing?'GÜNCELLENİYOR':'HAZIR','Yerel hesaplama',state.syncing?'gold':'green')}${metric('Son başarılı',state.lastSuccessfulSync?new Date(state.lastSuccessfulSync).toLocaleString('tr-TR'):'—','Europe/Istanbul')}${metric('Kayıt',state.records.length,'Veriler')}${metric('Öğrenme dönemi',state.performance.observations||0,'Bağımsız zaman penceresi')}${metric('Hata',state.logs.filter(x=>x.level==='error').length,'Son 300 log')}</div><div class="section-head"><h2>İşlem günlüğü</h2></div><div class="card list">${state.logs.slice(0,100).map(x=>`<div class="list-row"><div><strong>${html(x.message)}</strong><small>${new Date(x.ts).toLocaleString('tr-TR')} · ${html(JSON.stringify(x.meta))}</small></div><span class="badge ${x.level==='error'?'bad':x.level==='ok'?'ok':'warn'}">${x.level.toUpperCase()}</span></div>`).join('')}</div>`;}

window.showSub=(name,btn)=>{$$('.tabs button').forEach(x=>x.classList.remove('active'));btn.classList.add('active');$('#subContent').innerHTML=({history:historySub,performance:performanceSub,archive:archiveSub,status:statusSub,settings:settingsSub}[name])()};

window.showCriterion=k=>{const rows=(state.scores[k]||[]).slice(0,50),perf=state.performance.raw?.[k],cat=CRITERION_CATALOG[k];$('#dialogBody').innerHTML=`<h2>${k} · ${cat.name}</h2><p class="muted">${html(cat.desc)}</p><div class="card notice">Durum: ${perf?.status||'ADAY'} · Hedef isabet ${fmt((perf?.dualPrecision||0)*100,1)}% · Lift ${fmt(perf?.dualLift,2)}x · Alt güven ${fmt((perf?.dualLowerBound||0)*100,1)}% · Reel Top20 ${fmt((perf?.top20Precision||0)*100,1)}% · ≥%5 ${fmt((perf?.fivePctPrecision||0)*100,1)}% · ${perf?.predictions||0} tahmin · ${perf?.independentPeriods||0} bağımsız dönem</div>${rows.length?`<div class="table-wrap"><table><thead><tr><th>#</th><th>Hisse</th><th>Skor</th><th>Hedef Olasılığı</th><th>Günlük</th><th>ATR%</th><th>Hacim x</th></tr></thead><tbody>${rows.map((x,i)=>`<tr onclick="showDetail('${x.sym}')"><td>${i+1}</td><td class="symbol">${x.sym}</td><td>${fmt(x.score,2)}</td><td>${fmt((state.selection.find(y=>y.sym===x.sym)?.targetProbability||0)*100,1)}%</td><td>${pct(x.record.dayChange)}</td><td>${fmt(x.record.atrPct,1)}</td><td>${fmt(x.record.volumeBreakout,1)}</td></tr>`).join('')}</tbody></table></div>`:'<p>Sonuç yok.</p>'}`;$('#detailDialog').showModal()};

window.clearVerifiedData=async()=>{if(!confirm('Tüm doğrulanmış piyasa verileri silinsin mi? Arşiv korunur.'))return;await dbClear('records');await dbClear('bars');await dbClear('actions');await dbClear('behaviorProfiles');state.behaviorProfiles.clear();state.behaviorMemory={coverage:0,totalEvents:0,latestEvidenceId:null};state.records=[];state.recordMap.clear();state.selection=[];state.scores={};state.lastDerivedUpdate=null;state.dataMode='EMPTY';render();showAurumNotice('Doğrulanmış veriler silindi')};

window.resetApplication=async()=>{if(!confirm('Ayarlar, veriler, arşiv ve loglar tamamen silinsin mi?'))return;for(const s of ['settings','records','runs','logs','meta','bars','actions','criteria','backtests','snapshots','behaviorProfiles','genomeHistory','aiAudits','aiCandidates','aiEvents','universeHistory'])await dbClear(s);showAurumNotice('Uygulama sıfırlandı');setTimeout(()=>location.reload(),420)};

function importKey(value){return String(value??'').trim().toLocaleLowerCase('tr-TR').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9]/g,'')}
function importNumber(value){if(value==null||value==='')return null;if(typeof value==='number')return Number.isFinite(value)?value:null;let x=String(value).trim().replace(/\s/g,'');if(!x)return null;if(x.includes(',')&&x.includes('.')){if(x.lastIndexOf(',')>x.lastIndexOf('.'))x=x.replace(/\./g,'').replace(',','.');else x=x.replace(/,/g,'')}else if(x.includes(','))x=x.replace(',','.');const n=Number(x);return Number.isFinite(n)?n:null}
function importDate(value){if(value==null||value==='')return null;if(typeof value==='number'&&Number.isFinite(value)&&value>15000&&value<100000){const d=new Date(Date.UTC(1899,11,30)+Math.round(value)*86400000);return d.toISOString().slice(0,10)}const raw=String(value).trim(),m=raw.match(/^(\d{1,2})[.\/-](\d{1,2})[.\/-](\d{2,4})$/);if(m){let y=Number(m[3]);if(y<100)y+=2000;return `${String(y).padStart(4,'0')}-${m[2].padStart(2,'0')}-${m[1].padStart(2,'0')}`}return ymd(raw)}
function importPick(row,names){const wanted=new Set(names.map(importKey));for(const [k,v] of Object.entries(row||{}))if(wanted.has(importKey(k)))return v;return null}
function tabularImportObject(rows){
  const grp=new Map();
  for(const row of rows||[]){
    const sym=String(importPick(row,['symbol','sembol','ticker','kod','hisse','hisse kodu'])||'').trim().toLocaleUpperCase('tr-TR').replace(/\s+/g,''),date=importDate(importPick(row,['date','tarih','işlem tarihi','islem tarihi']));
    if(!sym||!date)continue;
    const open=importNumber(importPick(row,['open','açılış','acilis'])),high=importNumber(importPick(row,['high','yüksek','yuksek'])),low=importNumber(importPick(row,['low','düşük','dusuk'])),close=importNumber(importPick(row,['close','kapanış','kapanis','son'])),adjustedClose=importNumber(importPick(row,['adjusted close','adjustedclose','adj close','adjclose','düzeltilmiş kapanış','duzeltilmis kapanis'])),volume=importNumber(importPick(row,['volume','hacim']));
    if(close==null&&open==null&&high==null&&low==null)continue;
    const a=grp.get(sym)||[];a.push({date,open,high,low,close,adjustedClose,volume,sources:{close:'IMPORT'}});grp.set(sym,a);
  }
  if(!grp.size)throw new Error('Dosyada sembol/tarih/OHLCV sütunlarıyla eşleşen veri bulunamadı');
  return {records:[...grp.entries()].map(([symbol,bars])=>({symbol,bars:bars.sort((a,b)=>String(a.date).localeCompare(String(b.date))),fundamentals:{},live:null,actions:[],providers:['IMPORT'],conflicts:[]}))};
}
function matrixToImportRows(matrix){const rows=(matrix||[]).filter(r=>Array.isArray(r)&&r.some(v=>String(v??'').trim()!==''));if(rows.length<2)throw new Error('Tabloda başlık ve veri satırı bulunamadı');const headers=rows[0].map((x,i)=>String(x??'').trim()||`Sütun${i+1}`);return rows.slice(1).map(r=>Object.fromEntries(headers.map((h,i)=>[h,r[i]??''])))}
function zipU16(a,o){return a[o]|a[o+1]<<8}function zipU32(a,o){return (a[o]|a[o+1]<<8|a[o+2]<<16|a[o+3]<<24)>>>0}
async function inflateBytes(bytes,format='deflate-raw'){if(typeof DecompressionStream!=='function')throw new Error('Bu Android WebView sürümü sıkıştırılmış XLSX/PDF çözümlemeyi desteklemiyor');const ds=new DecompressionStream(format),stream=new Blob([bytes]).stream().pipeThrough(ds);return new Uint8Array(await new Response(stream).arrayBuffer())}
async function unzipEntries(buffer){const a=new Uint8Array(buffer),td=new TextDecoder('utf-8');let eocd=-1;for(let i=a.length-22;i>=Math.max(0,a.length-65558);i--)if(zipU32(a,i)===0x06054b50){eocd=i;break}if(eocd<0)throw new Error('XLSX ZIP dizini okunamadı');const count=zipU16(a,eocd+10),central=zipU32(a,eocd+16),out=new Map();let p=central;for(let i=0;i<count;i++){if(zipU32(a,p)!==0x02014b50)throw new Error('XLSX merkez dizini bozuk');const method=zipU16(a,p+10),comp=zipU32(a,p+20),nameLen=zipU16(a,p+28),extraLen=zipU16(a,p+30),commentLen=zipU16(a,p+32),local=zipU32(a,p+42),name=td.decode(a.slice(p+46,p+46+nameLen));if(zipU32(a,local)!==0x04034b50)throw new Error('XLSX yerel kayıt başlığı bozuk');const ln=zipU16(a,local+26),le=zipU16(a,local+28),start=local+30+ln+le,raw=a.slice(start,start+comp);let data;if(method===0)data=raw;else if(method===8)data=await inflateBytes(raw,'deflate-raw');else throw new Error(`XLSX sıkıştırma yöntemi desteklenmiyor (${method})`);out.set(name,data);p+=46+nameLen+extraLen+commentLen}return out}
function xmlText(bytes){return new TextDecoder('utf-8').decode(bytes)}
function cellColumn(ref){let n=0;for(const ch of String(ref||'').match(/^[A-Z]+/i)?.[0]||''){n=n*26+(ch.toUpperCase().charCodeAt(0)-64)}return Math.max(0,n-1)}
async function xlsxImportObject(file){const z=await unzipEntries(await file.arrayBuffer()),parser=new DOMParser(),shared=[];if(z.has('xl/sharedStrings.xml')){const doc=parser.parseFromString(xmlText(z.get('xl/sharedStrings.xml')),'application/xml');for(const si of [...doc.getElementsByTagName('si')])shared.push([...si.getElementsByTagName('t')].map(x=>x.textContent||'').join(''))}const sheetName=[...z.keys()].filter(x=>/^xl\/worksheets\/sheet\d+\.xml$/i.test(x)).sort((a,b)=>a.localeCompare(b,undefined,{numeric:true}))[0];if(!sheetName)throw new Error('XLSX içinde çalışma sayfası bulunamadı');const doc=parser.parseFromString(xmlText(z.get(sheetName)),'application/xml'),matrix=[];for(const row of [...doc.getElementsByTagName('row')]){const arr=[];for(const c of [...row.getElementsByTagName('c')]){const idx=cellColumn(c.getAttribute('r')),type=c.getAttribute('t')||'',v=c.getElementsByTagName('v')[0]?.textContent??'',inline=[...c.getElementsByTagName('t')].map(x=>x.textContent||'').join('');arr[idx]=type==='s'?shared[Number(v)]??v:type==='inlineStr'?inline:type==='b'?(v==='1'?'TRUE':'FALSE'):v}matrix.push(arr)}return tabularImportObject(matrixToImportRows(matrix))}
function pdfAscii85(bytes){const src=new TextDecoder('ascii').decode(bytes).replace(/\s+/g,'').replace(/^<~/,'').replace(/~>.*$/,'');const out=[];let group='';const flush=(g,count)=>{let x=0;for(const ch of g.padEnd(5,'u'))x=x*85+(ch.charCodeAt(0)-33);const vals=[(x>>>24)&255,(x>>>16)&255,(x>>>8)&255,x&255];out.push(...vals.slice(0,count-1))};for(const ch of src){if(ch==='z'&&!group){out.push(0,0,0,0);continue}if(ch<'!'||ch>'u')continue;group+=ch;if(group.length===5){flush(group,5);group=''}}if(group.length>1)flush(group,group.length);return new Uint8Array(out)}
function pdfUnescape(s){return String(s).replace(/\\([nrtbf()\\])/g,(_,c)=>({n:'\n',r:'\r',t:'\t',b:'\b',f:'\f','(':'(',')':')','\\':'\\'}[c]??c)).replace(/\\([0-7]{1,3})/g,(_,o)=>String.fromCharCode(parseInt(o,8))).replace(/\\\r?\n/g,'')}
function pdfTextFromContent(content){let out='',last=0,re=/(\((?:\\.|[^\\)])*\)|<([0-9A-Fa-f\s]+)>|\[(?:.|\n|\r)*?\])\s*(Tj|TJ|'|")|\b(T\*|[-+\d.]+\s+[-+\d.]+\s+T[dD]|ET)\b/g,m;while((m=re.exec(content))){if(m[4]){out+='\n';continue}const tok=m[1]||'',op=m[3];if(tok.startsWith('('))out+=pdfUnescape(tok.slice(1,-1));else if(tok.startsWith('<')){const h=tok.slice(1,-1).replace(/\s/g,'');let s='';for(let i=0;i+1<h.length;i+=2)s+=String.fromCharCode(parseInt(h.slice(i,i+2),16));out+=s}else if(tok.startsWith('[')){const pieces=[...tok.matchAll(/\((?:\\.|[^\\)])*\)/g)].map(x=>pdfUnescape(x[0].slice(1,-1)));out+=pieces.join('')}out+=(op==="'"||op==='"')?'\n':' '}return out}
async function pdfExtractText(file){const a=new Uint8Array(await file.arrayBuffer()),latin=new TextDecoder('latin1').decode(a);let out='',pos=0;while(true){const s=latin.indexOf('stream',pos);if(s<0)break;let start=s+6;if(latin[start]==='\r'&&latin[start+1]==='\n')start+=2;else if(latin[start]==='\n'||latin[start]==='\r')start++;const end=latin.indexOf('endstream',start);if(end<0)break;const dictStart=Math.max(0,latin.lastIndexOf('<<',s)),dict=latin.slice(dictStart,s),raw=a.slice(start,end-(latin[end-1]==='\n'?1:0)-(latin[end-2]==='\r'?1:0));try{let bytes=raw;if(/ASCII85Decode/.test(dict))bytes=pdfAscii85(bytes);if(/\/FlateDecode/.test(dict))bytes=await inflateBytes(bytes,'deflate');out+='\n'+pdfTextFromContent(new TextDecoder('latin1').decode(bytes))}catch{}pos=end+9}return out.replace(/\u0000/g,' ').replace(/[ \t]+/g,' ').replace(/\n{3,}/g,'\n\n').trim()}
function pdfImportObjectFromText(text){const lines=String(text||'').split(/\r?\n/).map(x=>x.trim()).filter(Boolean),rows=[];const rowRe=/^([A-ZÇĞİÖŞÜ0-9._-]{2,16})\s+(\d{4}[.\/-]\d{1,2}[.\/-]\d{1,2}|\d{1,2}[.\/-]\d{1,2}[.\/-]\d{2,4})\s+(-?[\d.,]+)\s+(-?[\d.,]+)\s+(-?[\d.,]+)\s+(-?[\d.,]+)(?:\s+(-?[\d.,]+))?/i;for(const line of lines){const m=line.match(rowRe);if(m)rows.push({symbol:m[1],date:m[2],open:m[3],high:m[4],low:m[5],close:m[6],volume:m[7]||''})}if(rows.length)return tabularImportObject(rows);for(let i=0;i<lines.length-1;i++){const sep=lines[i].includes(';')?';':lines[i].includes('\t')?'\t':null;if(!sep)continue;const headers=lines[i].split(sep);if(!headers.some(x=>['symbol','sembol','hisse','kod'].includes(importKey(x)))||!headers.some(x=>['date','tarih'].includes(importKey(x))))continue;const matrix=[headers];for(let j=i+1;j<lines.length;j++){const cells=lines[j].split(sep);if(cells.length<2)break;matrix.push(cells)}return tabularImportObject(matrixToImportRows(matrix))}throw new Error('PDF içindeki piyasa tablosu okunamadı. PDF metin katmanlı olmalı ve sembol, tarih, OHLCV alanlarını içermelidir')}
async function importObjectFromFile(file){const name=String(file?.name||'').toLowerCase();if(name.endsWith('.json'))return JSON.parse(await file.text());if(name.endsWith('.csv'))return tabularImportObject(parseCSV(await file.text()));if(name.endsWith('.xlsx'))return xlsxImportObject(file);if(name.endsWith('.pdf')){const text=await pdfExtractText(file);if(!text)throw new Error('PDF metin katmanı içermiyor; taranmış/görüntü PDF doğrudan içe aktarılamaz');return pdfImportObjectFromText(text)}throw new Error('Desteklenmeyen dosya türü. XLSX, CSV, PDF veya JSON seçin')}

async function importData(text,name){
  const CP_KEY='importCheckpoint';
  const saveCp=async cp=>dbPut('meta',{key:CP_KEY,value:{...cp,updatedAt:nowISO()}});
  try{
    let checkpoint=(await dbGet('meta',CP_KEY))?.value||null,obj,bundles,fileName=name||text?.name||checkpoint?.name||'devam-eden-aktarim';
    if(text!=null){
      if(typeof Blob!=='undefined'&&text instanceof Blob)obj=await importObjectFromFile(text);
      else if(String(fileName).toLowerCase().endsWith('.csv'))obj=tabularImportObject(parseCSV(String(text)));
      else obj=JSON.parse(String(text));
      bundles=Array.isArray(obj)?obj:obj.records||[];
      const signature=`${fileName}|${bundles.length}|${bundles.map(x=>String(x.symbol||x.sym||'')).join('|')}`;
      checkpoint={version:3,name:fileName,signature,status:'RUNNING',startedAt:nowISO(),completedSymbols:[],failed:{},bundles};
      try{localStorage.setItem('aurum.operation.resumeCheckpoint.v3',JSON.stringify({version:3,kind:'IMPORT',status:'RUNNING',startedAt:checkpoint.startedAt,updatedAt:nowISO(),name:fileName}))}catch{}
      await saveCp(checkpoint);
    }else{
      if(!checkpoint||!Array.isArray(checkpoint.bundles))throw new Error('Devam ettirilecek içe aktarma kontrol noktası yok');
      bundles=checkpoint.bundles;checkpoint.status='RUNNING';checkpoint.resumeCount=Number(checkpoint.resumeCount||0)+1;try{localStorage.setItem('aurum.operation.resumeCheckpoint.v3',JSON.stringify({version:3,kind:'IMPORT',status:'RUNNING',updatedAt:nowISO(),name:fileName,resumeCount:checkpoint.resumeCount}))}catch{};await saveCp(checkpoint);
    }
    const done=new Set((checkpoint.completedSymbols||[]).map(x=>String(x).toUpperCase()));let n=0;
    let indexBundle=(await dbGet('meta','indexBundle'))?.value||{bars:[]};
    for(const b of bundles){
      const sym=String(b.symbol||b.sym||'').toUpperCase();if(sym&&done.has(sym))continue;
      const incoming=b.bars?{...b,symbol:sym||b.symbol}:{symbol:sym,bars:(b.series?.date||[]).map((d,i)=>({date:d,open:b.series.open?.[i],high:b.series.high?.[i],low:b.series.low?.[i],close:b.series.close?.[i],adjustedClose:b.series.calcClose?.[i],volume:b.series.volume?.[i],sources:{close:'IMPORT'}})),fundamentals:b.fundamentals||{},live:finite(b.livePrice)!=null?{price:finite(b.livePrice),provider:'IMPORT'}:null,actions:b.actions||[],providers:['IMPORT'],conflicts:[]};
      if(!incoming.symbol)continue;
      try{
        const previous=state.recordMap.get(incoming.symbol),merged=previous?mergeBundles(incoming.symbol,[bundleFromRecord(previous),incoming]):incoming,rec=enrichBundle(merged,indexBundle);
        await persistRecord(rec);state.recordMap.set(rec.sym,rec);done.add(rec.sym);delete checkpoint.failed?.[rec.sym];checkpoint.completedSymbols=[...done];checkpoint.lastCompletedSymbol=rec.sym;await saveCp(checkpoint);n++;
      }catch(e){checkpoint.failed=checkpoint.failed||{};checkpoint.failed[incoming.symbol]={error:e?.message||String(e),at:nowISO()};checkpoint.status='INTERRUPTED';await saveCp(checkpoint);throw e;}
    }
    state.records=[...state.recordMap.values()];
    const remaining=bundles.map(x=>String(x.symbol||x.sym||'').toUpperCase()).filter(Boolean).filter(x=>!done.has(x));
    if(remaining.length){checkpoint.status='INTERRUPTED';checkpoint.remaining=remaining;await saveCp(checkpoint);throw new Error(`${remaining.length} kayıt tamamlanamadı; mevcut veriler korunarak kontrol noktası kaydedildi`);}
    checkpoint.status='COMPLETED';checkpoint.completedAt=nowISO();checkpoint.bundles=[];await saveCp(checkpoint);await dbDelete('meta',CP_KEY);try{const x=JSON.parse(localStorage.getItem('aurum.operation.resumeCheckpoint.v3')||'null');if(x?.kind==='IMPORT')localStorage.removeItem('aurum.operation.resumeCheckpoint.v3')}catch{};
    const snapshotBatchId=await persistLiveSnapshots();/* R58: import updates Veriler only; Kn/K_Tarihsel/S remain explicit manual sequence steps. */await log('ok','Veri içe aktarıldı ve mevcut kayıtlarla birleştirildi',{file:fileName,records:n,total:done.size});render();showAurumNotice(`${n} kayıt içe aktarıldı; mevcut veriler korundu`);return true;
  }catch(e){try{const x=JSON.parse(localStorage.getItem('aurum.operation.resumeCheckpoint.v3')||'{}');if(x?.kind==='IMPORT'){x.status='INTERRUPTED';x.lastError=e?.message||String(e);x.updatedAt=nowISO();localStorage.setItem('aurum.operation.resumeCheckpoint.v3',JSON.stringify(x))}}catch{};await log('error','İçe aktarma kesildi; kontrol noktasından devam edilebilir',{error:e.message});showAurumNotice('İçe aktarma kesildi; mevcut veriler korundu ve devam noktası kaydedildi','error',4200);return false;}
}

function quickAccess(){return `<div class="section-head"><div class="section-title"><h2>Hızlı Erişim</h2></div><small>Temel çalışma tabloları</small></div><div class="quick-grid"><button class="quick-card" onclick="goPage('data')"><span class="quick-icon">▦</span><strong>Veriler</strong><small>Doğrulanmış ham, teknik ve tarihsel veri merkezi</small></button><button class="quick-card" onclick="goPage('criteria')"><span class="quick-icon">∑</span><strong>Kn Tabloları</strong><small>K1–K12 ve K10 konsensüs sıralamaları</small></button><button class="quick-card" onclick="goPage('history')"><span class="quick-icon">⌁</span><strong>K_Tarihsel</strong><small>Kriterlerin reel sonuçlara göre dönemsel başarısı</small></button><button class="quick-card" onclick="goPage('selection')"><span class="quick-icon">★</span><strong>S Tablosu</strong><small>Nihai ilk 20 seçim ve canlı performans</small></button><button class="quick-card" onclick="goPage('ai')"><span class="quick-icon">✦</span><strong>Yapay Zekâ Merkezi</strong><small>Günlük denetim, aday model ve kontrollü doğrulama</small></button></div>`;}

function recordsTable(rows){return `<div class="table-wrap"><table><thead><tr><th>Hisse</th><th>Tarih</th><th>Anlık</th><th>Değişim</th><th>Hacim x</th><th>ATR%</th><th>Rel5</th><th>Davranış</th><th>89 Özellik DNA</th><th>Karakter</th><th>Maliyet</th><th>Rejim</th><th>Kalite</th><th>Kaynak</th></tr></thead><tbody>${rows.map(x=>`<tr onclick="showDetail('${x.sym}')"><td class="symbol">${x.sym}</td><td>${x.latestDate}</td><td>${fmt(x.livePrice)}</td><td class="${x.dayChange>=0?'green':'red'}">${pct(x.dayChange)}</td><td>${fmt(x.volumeBreakout,2)}</td><td>${fmt(x.atrPct,2)}</td><td>${pct(Number.isFinite(x.retTL5)&&Number.isFinite(x.retXU5)?x.retTL5-x.retXU5:null)}</td><td><b class="gold">${fmt(x.behaviorScore,1)}</b><small>${fmt((x.behaviorProfile?.dualRate||0)*100,1)}% çift hedef</small></td><td><b class="dna-score">${fmt(x.genomeScore,1)}</b><small>${fmt((x.genomeProbability||0)*100,1)}% · ${x.genomeProfile?.featureCount||0}/${GENOME_TRAIT_COUNT}</small></td><td>${html(x.genomeType||x.behaviorType||'—')}</td><td>${pct(x.estimatedCostPct)}</td><td>${x.marketRegime}</td><td>${x.quality}</td><td>${html(x.source)}</td></tr>`).join('')}</tbody></table></div>`;}

function selectionTable(rows){if(!rows.length)return `<div class="card notice">Gerçek veri henüz yok. “Verileri Çalıştır” ile kaynak zincirini çalıştırın.</div>`;return `<div class="table-wrap"><table><thead><tr><th>#</th><th>Hisse</th><th>Veri Zamanı</th><th>Anlık %</th><th>Anlık</th><th>Maliyet</th><th>Giriş zamanı</th><th>Getiri %</th><th>KnzTOP20</th><th>S gerekçesi</th><th>Puan</th><th>Hedef Olasılığı</th><th>Maks.</th><th>Risk</th><th>Kalite</th></tr></thead><tbody>${rows.map((x,i)=>{const pending=x.entryStatus==='PENDING',entryLabel=pending?'Ertesi açılış bekleniyor':x.entryStatus==='ACTIVE'?'Aktif':'Bekliyor',rec=state.recordMap?.get?.(x.sym)||state.records?.find?.(r=>r.sym===x.sym),instant=safeRecordDayChange(rec),reasons=(x.targetReasons||[]).slice(0,3).join(' · '),criteria=(x.supportingCriteria||[]).join(' · ');return `<tr onclick="showDetail('${x.sym}')"><td><span class="rank">${i+1}</span></td><td><span class="symbol">${x.sym}</span></td><td>${typeof formatTableTime==='function'?html(formatTableTime(rec?.marketDataAt||rec?.provenance?.marketAt||rec?.apiAccessedAt||rec?.storedAt||null)):'—'}</td><td class="${(instant??0)>=0?'green':'red'}">${pct(instant)}</td><td>${fmt(x.livePrice)}</td><td>${pending?'<span class="badge warn">Açılış bekleniyor</span>':Number(x.entryPrice)>0?fmt(x.entryPrice):'<span class="badge warn">Doğrulanıyor</span>'}<small>${entryLabel}</small></td><td>${pending?html(x.signalTime||'Sinyal kaydı mevcut'):x.entryTime?html(x.entryTime):'<span class="badge warn">Doğrulanıyor</span>'}</td><td class="${Number(x.currentReturn)>=0?'green':'red'}">${Number.isFinite(x.currentReturn)?pct(x.currentReturn):(pending?'<span class="badge warn">Açılış bekleniyor</span>':'<span class="badge warn">Doğrulanıyor</span>')}</td><td>${html(criteria||'—')}</td><td>${html(reasons||'—')}</td><td><span class="scorebar"><i style="width:${x.totalScore}%"></i></span>${fmt(x.totalScore,1)}</td><td><b class="target-prob">${fmt(x.targetProbability*100,1)}%</b></td><td class="green">${pct(x.maxPotential)}</td><td><span class="pill ${x.riskLevel==='Yüksek'?'risk-high':x.riskLevel==='Orta'?'risk-mid':'risk-low'}">${x.riskLevel}</span></td><td>${x.quality}/100<small>${html(x.source)}</small></td></tr>`}).join('')}</tbody></table></div>`;}
function overview(){const s=state.selection,avg=mean(s.map(x=>x.dayChange)),med=median(s.map(x=>x.dayChange)),evaluated=latestTargetRun(),q=mean(state.records.map(x=>x.quality)),lm=learningMomentum(),profiles=[...state.behaviorProfiles.values()];return `${quickAccess()}<div class="section-head"><div class="section-title"><h2>Sonuç ve Öğrenme Özeti</h2></div><small>Canlı sistem görünümü</small></div><div class="grid metrics aurum-overview-metrics">${metric('Aktif seçim',s.length,'S · Nihai liste')}${metric('Hedef isabet',evaluated?fmt(evaluated.metrics.precisionDual20*100,1)+'%':'—','2S Top20 + hedef temas ≥%'+state.settings.targetReturnPct)}${metric('Öğrenme puanı',fmt(lm.score,1)+'/100',lm.delta==null?'Yeni kanıt bekleniyor':`7 dönem değişim ${lm.delta>=0?'+':''}${fmt(lm.delta*100,1)} puan`,lm.delta>=0?'green':'red')}${metric('Davranış kapsaması',fmt((state.behaviorMemory.coverage||0)*100,1)+'%',`${profiles.length} hisse · 252 seans`)}${metric('DNA kapsaması',fmt((state.behaviorMemory.genomeCoverage||0)*100,1)+'%',`${GENOME_TRAIT_COUNT} özellik · K12`)}${metric('Ortalama günlük',pct(avg),'Seçili hisseler',avg>=0?'green':'red')}${metric('Medyan günlük',pct(med),'Seçili hisseler',med>=0?'green':'red')}${metric('Veri kalite',q?fmt(q,0)+'/100':'—',`${state.records.length} kayıt`)}${metric('Model',MODEL_VERSION,'Şampiyon–aday + 89 özellikli DNA')}</div><div class="section-head"><div class="section-title"><h2>S · Nihai Seçim</h2></div><small>İlk 10 görünüm · ilk 20 S ekranında</small></div>${selectionTable(s.slice(0,10))}<div class="section-head"><div class="section-title"><h2>Öğrenme disiplini</h2></div></div><div class="grid two-col aurum-overview-discipline"><div class="card gold-edge"><b class="gold aurum-decision-label">${html(String(state.performance.lastDecision||'Bekleme').replaceAll('_',' ').toLowerCase().replace(/(^|\s)\S/g,m=>m.toUpperCase()))}</b><p class="muted">Aday katkı yalnız ileri dönem doğrulamasında şampiyonu geçerse etkinleşir.</p><button class="ghost-btn" onclick="goPage('learning')">Öğrenme ve Davranış Modülünü Aç</button></div><div class="card list">${Object.entries(state.sourceStats).map(([k,v])=>`<div class="list-row"><strong>${html(k)}</strong><span>${v} sembol</span></div>`).join('')||'<p class="muted">Bu oturumda kaynak çalıştırılmadı.</p>'}</div></div>`;}

function renderSelectionBody(){return `${selectionTable(state.selection)}<div class="section-head"><h2>Hedef</h2></div><div class="card notice aurum-brief-notice">Reel Top20 üyeliği ve maliyet sonrası hedef getiri birlikte sağlanır.</div>`;}

