function behaviorTable(profiles){return `<div class="table-wrap"><table><thead><tr><th>Hisse</th><th>Karakter</th><th>Davranış Skoru</th><th>Çift Hedef</th><th>Lift</th><th>Güven</th><th>Aktif Örüntüler</th><th>252G Gözlem</th><th>Toplam Seans</th><th>Rejim</th></tr></thead><tbody>${profiles.map(p=>`<tr onclick="showBehaviorDetail('${p.sym}')"><td><button type="button" class="symbol aurum-symbol-link" onclick="event.stopPropagation();showDetail('${p.sym}')">${p.sym}</button></td><td>${html(p.character?.type||'—')}</td><td><b class="gold">${fmt(p.score,1)}</b></td><td>${fmt((p.dualRate||0)*100,1)}%</td><td>${fmt(p.lift,2)}x</td><td>${fmt(p.confidence,0)}/100</td><td>${p.activePatterns.map(x=>`<span class="pattern-chip">${html(x.name)}</span>`).join('')||'—'}</td><td>${p.recentObservations}</td><td>${p.lifetimeSessions}</td><td>${p.currentRegime}</td></tr>`).join('')}</tbody></table></div>`;}

function behaviorSub(){const p=[...state.behaviorProfiles.values()].sort((a,b)=>b.score-a.score||a.sym.localeCompare(b.sym));return `<div class="grid metrics">${metric('Profil',p.length,'Hisse karakteri')}${metric('Yeterli örnek',p.filter(x=>x.recentObservations>=state.settings.behaviorMinSamples).length,`≥${state.settings.behaviorMinSamples} olay`)}${metric('Ort. davranış güveni',fmt(mean(p.map(x=>x.confidence)),1)+'/100','Bayes küçültmeli')}${metric('Bellek olayı',state.behaviorMemory.totalEvents||0,'Son 252 seans örnekleri')}</div><div class="card notice" style="margin-top:12px">252 seans ve doğrulanmış geçmiş birlikte değerlendirilir; az örnekler evren ortalamasına küçültülür.</div><div class="section-head"><h2>Hisse davranış profilleri</h2><small id="behaviorCount">${p.length} hisse</small></div><div class="table-tools"><input class="search-input" placeholder="Hisse veya karakter ara…" oninput="filterBehavior(this.value)"></div><div id="behaviorContent">${behaviorTable(p)}</div>`;}

window.filterBehavior=q=>{const z=String(q||'').toLocaleUpperCase('tr-TR'),p=[...state.behaviorProfiles.values()].filter(x=>!z||x.sym.includes(z)||String(x.character?.type||'').toLocaleUpperCase('tr-TR').includes(z)).sort((a,b)=>b.score-a.score);$('#behaviorContent').innerHTML=behaviorTable(p);$('#behaviorCount').textContent=`${p.length} hisse`;};

function learningOverviewSub(){const lm=learningMomentum(),h=(state.performance.history||[]).slice(0,30).reverse(),accepted=(state.performance.history||[]).filter(x=>x.decision==='ONAYLANDI').length,rejected=(state.performance.history||[]).filter(x=>x.decision==='REDDEDİLDİ').length,pts=h.map((x,i)=>({x:i,v:Number.isFinite(x.candidateScore)?x.candidateScore:Number.isFinite(x.currentScore)?x.currentScore:null,date:x.date,decision:x.decision})).filter(x=>Number.isFinite(x.v)),w=720,hh=180,pad=24,minv=pts.length?Math.min(...pts.map(x=>x.v)):0,maxv=pts.length?Math.max(...pts.map(x=>x.v)):100,span=Math.max(1,maxv-minv),xy=pts.map((p,i)=>({ ...p, px:pad+(w-pad*2)*(pts.length<=1?0:i/(pts.length-1)), py:hh-pad-(hh-pad*2)*((p.v-minv)/span)})),poly=xy.map(p=>`${p.px.toFixed(1)},${p.py.toFixed(1)}`).join(' '),last=pts.at(-1),first=pts[0],delta=(last&&first)?last.v-first.v:null,dir=delta==null?'—':delta>0?'Yukarı':delta<0?'Aşağı':'Yatay';return `<div class="grid metrics">${metric('Öğrenme puanı',fmt(lm.score,1)+'/100','')}${metric('Son 7 dönem',Number.isFinite(lm.last7)?fmt(lm.last7*100,1)+'%':'—','Precision@20')}${metric('Değişim',Number.isFinite(lm.delta)?`${lm.delta>=0?'+':''}${fmt(lm.delta*100,1)} puan`:'—','7 dönem',lm.delta>=0?'green':'red')}${metric('Davranış kapsaması',fmt((state.behaviorMemory.coverage||0)*100,1)+'%','Yeterli örnek')}${metric('Onaylanan aday',accepted,'')}${metric('Reddedilen aday',rejected,'')}${metric('Bağımsız dönem',state.performance.observations||0,'Tekilleştirilmiş')}${metric('Son karar',state.performance.lastDecision||'BEKLEME','Model kapısı')}</div><div class="section-head"><h2>Günlük öğrenme eğilimi</h2><small>Son değer ${last?fmt(last.v,1):'—'} · değişim ${delta==null?'—':`${delta>=0?'+':''}${fmt(delta,1)}`} · ${dir}</small></div><div class="card aurum-learning-chart">${xy.length?`<svg viewBox="0 0 ${w} ${hh}" role="img" aria-label="Günlük öğrenme performansı çizgi grafiği"><g class="chart-grid">${[.25,.5,.75].map(q=>`<line x1="${pad}" x2="${w-pad}" y1="${(pad+(hh-pad*2)*q).toFixed(1)}" y2="${(pad+(hh-pad*2)*q).toFixed(1)}"/>`).join('')}</g><polyline class="chart-line" points="${poly}" fill="none"/>${xy.map(p=>`<circle class="chart-dot" cx="${p.px}" cy="${p.py}" r="3"><title>${html(p.date||'')} · ${fmt(p.v,1)} · ${html(p.decision||'')}</title></circle>`).join('')}</svg>`:'<p class="muted">Henüz doğrulama geçmişi yok.</p>'}<p class="aurum-chart-note"><b>Nasıl okunur?</b> Çizgi, kaydedilmiş günlük model/aday performans puanının zaman içindeki yönünü gösterir. Yükseliş tek başına canlı modele terfi anlamına gelmez; örneklem yeterliliği, ileri dönem doğrulaması ve şampiyon modele karşı üstünlük kapıları ayrıca uygulanır. Düşüş, son dönemlerde ölçülen performansın zayıfladığını gösterir; geçmişe gelecek veri sızdırılmaz.</p></div>`;}
function genomeTable(profiles){return `<div class="table-wrap"><table><thead><tr><th>Hisse</th><th>DNA Karakteri</th><th>K12 Skoru</th><th>Benzer Gün Hedefi</th><th>Lift</th><th>Güven</th><th>Özellik</th><th>Benzer Gün</th><th>Mevcut Senaryo</th><th>Öne Çıkan Huylar</th></tr></thead><tbody>${profiles.map(p=>{const g=p.genome||{};return `<tr onclick="showGenomeDetail('${p.sym}')"><td><button type="button" class="symbol aurum-symbol-link" onclick="event.stopPropagation();showDetail('${p.sym}')">${p.sym}</button></td><td>${html(g.temperament||'—')}</td><td><b class="dna-score">${fmt(g.score,1)}</b></td><td>${fmt((g.dualRate||0)*100,1)}%</td><td>${fmt(g.lift,2)}x</td><td>${fmt(g.confidence,0)}/100</td><td>${g.featureCount||0}/${g.totalFeatures||GENOME_TRAIT_COUNT}</td><td>${g.analog?.neighbors||0}<small>etkin n ${fmt(g.analog?.effectiveN,1)}</small></td><td>${html(g.currentScenario||'—')}<small>${fmt((g.currentScenarioStats?.dualRate||0)*100,1)}%</small></td><td>${(g.topTraits||[]).slice(0,3).map(x=>`<span class="trait-chip">${html(x.label)}</span>`).join('')||'—'}</td></tr>`}).join('')}</tbody></table></div>`;}

function genomeSub(){const p=[...state.behaviorProfiles.values()].filter(x=>x.genome).sort((a,b)=>(b.genome?.score||0)-(a.genome?.score||0)||a.sym.localeCompare(b.sym));return `<div class="grid metrics">${metric('DNA profili',p.length,'Hisse bazlı')}${metric('Özellik kataloğu',GENOME_TRAIT_COUNT,'Piyasa, hacim, hız, rejim ve temel')}${metric('Yeterli kapsama',fmt((state.behaviorMemory.genomeCoverage||0)*100,1)+'%',`≥50 özellik ve ≥${state.settings.genomeMinAnalogs} benzer gün`)}${metric('Ort. K12 güveni',fmt(mean(p.map(x=>x.genome?.confidence)),1)+'/100','Benzer gün + senaryo')}${metric('DNA arşivi',state.genomeHistory.length,'Günlük profil anlık görüntüsü')}</div><div class="card notice" style="margin-top:12px">Davranış DNA, 89 özellik kataloğundan ölçülebilen istatistiksel profildir; yalnız geçmiş benzer günler kullanılır.</div><div class="section-head"><h2>Hisse davranış DNA profilleri</h2><small id="genomeCount">${p.length} hisse</small></div><div class="table-tools"><input class="search-input" placeholder="Hisse, karakter veya özellik ara…" oninput="filterGenome(this.value)"><span class="badge ok">${GENOME_TRAIT_COUNT} ÖZELLİK</span></div><div id="genomeContent">${genomeTable(p)}</div>`;}

window.filterGenome=q=>{const z=String(q||'').toLocaleUpperCase('tr-TR'),p=[...state.behaviorProfiles.values()].filter(x=>{const g=x.genome||{};return !z||x.sym.includes(z)||String(g.temperament||'').toLocaleUpperCase('tr-TR').includes(z)||(g.topTraits||[]).some(t=>String(t.label||'').toLocaleUpperCase('tr-TR').includes(z));}).sort((a,b)=>(b.genome?.score||0)-(a.genome?.score||0));$('#genomeContent').innerHTML=genomeTable(p);$('#genomeCount').textContent=`${p.length} hisse`;};

