async function saveJsonExport(fileName,text){
  if(String(location.href||'').startsWith('file:///android_asset/')&&typeof window.prompt==='function'){
    window.prompt('aurum://complete',String(text));
    return true;
  }
  const blob=new Blob([String(text)],{type:'application/json;charset=utf-8'});
  if(typeof window.showSaveFilePicker==='function'){
    try{
      const handle=await window.showSaveFilePicker({suggestedName:String(fileName||'aurum-export.json'),types:[{description:'Aurum JSON yedeği',accept:{'application/json':['.json']}}]});
      const writable=await handle.createWritable();await writable.write(blob);await writable.close();return true;
    }catch(e){if(e?.name==='AbortError')throw new Error('Dışa aktarma iptal edildi');if(!['NotSupportedError','SecurityError'].includes(String(e?.name||'')))throw e;}
  }
  const url=URL.createObjectURL(blob);
  try{const a=document.createElement('a');a.href=url;a.download=String(fileName||'aurum-export.json');a.rel='noopener';a.style.display='none';(document.body||document.documentElement).appendChild(a);a.click();a.remove();return true;}finally{setTimeout(()=>URL.revokeObjectURL(url),15000);}
}
window.exportData=async()=>{try{const payload=deepSecretSanitize({version:VERSION,modelVersion:MODEL_VERSION,exportedAt:nowISO(),settings:{...state.settings,openaiApiKey:''},records:state.records,runs:state.runs,performance:state.performance,behaviorProfiles:[...state.behaviorProfiles.values()],genomeHistory:state.genomeHistory,aiAudits:state.ai.audits,aiCandidates:state.ai.candidates}),fileName=`aurum-bist-analiz-${trParts().date}.json`;await saveJsonExport(fileName,JSON.stringify(payload,null,2));await log('ok','Gizli alanlardan arındırılmış veri seçilen konuma dışa aktarıldı');showAurumNotice('Android Farklı Kaydet ekranı açıldı; konumu seçip Kaydet’e dokunun','success',4200);}catch(error){await log('error','Veri dışa aktarılamadı',{error:error?.message||String(error)});showAurumNotice(`Veri dışa aktarılamadı: ${error?.message||error}`,'error',4800);}};

function normalizeOpenAIKey(raw){const text=String(raw??'').normalize('NFKC').trim();return /^sk-[A-Za-z0-9_\-]{20,}$/.test(text)?text:'';}

function aiConfigured(){return !!(state.settings.aiEnabled&&globalThis.AurumNativeAI?.configured?.());}

function openAIErrorMessage(status,obj,requestId){
  const code=obj?.error?.code||obj?.code||'',type=obj?.error?.type||obj?.type||'',msg=obj?.error?.message||obj?.message||`OpenAI HTTP ${status}`;
  const retryable=status===408||status===409||status===429||status>=500;
  return `${msg}${code?` · ${code}`:''}${type?` · ${type}`:''}${requestId?` · İstek ${requestId}`:''}${retryable?' · Yeniden denenebilir':''}`;
}

function extractOpenAIOutput(response){
  if(response?.status==='incomplete')throw new Error(`OpenAI yanıtı tamamlanmadı: ${response?.incomplete_details?.reason||'bilinmiyor'}`);
  const refusals=[],texts=[];
  if(typeof response?.output_text==='string'&&response.output_text.trim())texts.push(response.output_text);
  for(const item of response?.output||[])for(const c of item?.content||[]){
    if(c?.type==='refusal'||c?.refusal)refusals.push(c.refusal||c.text||'Model isteği reddetti');
    if((c?.type==='output_text'||c?.type==='text')&&typeof c.text==='string')texts.push(c.text);
  }
  if(refusals.length)throw new Error(`OpenAI refusal: ${refusals.join(' · ')}`);
  const raw=texts.find(x=>x&&x.trim());if(!raw)throw new Error(`OpenAI çıktısı bulunamadı · durum ${response?.status||'bilinmiyor'} · yanıt ${response?.id||'—'}`);
  try{return JSON.parse(raw)}catch{throw new Error(`OpenAI yapılandırılmış çıktısı ayrıştırılamadı · yanıt ${response?.id||'—'}`)}
}

async function openAIRequest({schemaName,schema,instructions,input,timeout=180000}){
  if(!state.settings.aiEnabled||!globalThis.AurumNativeAI?.configured?.())throw new Error('OpenAI güvenli bağlantısı yapılandırılmadı');
  const health=await openAIHealthCheck(),started=nowISO(),model=health.model;
  state.ai.health=health;state.settings.openaiModel=model;
  const payload={model,input:[{role:'system',content:[{type:'input_text',text:instructions}]},{role:'user',content:[{type:'input_text',text:JSON.stringify(deepSecretSanitize(input))}]}],max_output_tokens:Number(state.settings.openaiMaxOutputTokens||8000),text:{format:{type:'json_schema',name:schemaName,strict:true,schema}},store:false};
  if(String(state.settings.openaiReasoningEffort||'').trim())payload.reasoning={effort:state.settings.openaiReasoningEffort};
  const res=await globalThis.AurumNativeAI.request('/v1/responses','POST',payload,timeout),requestId=res.requestId||'';let obj={};
  try{obj=res.body?JSON.parse(res.body):{}}catch{throw new Error('OpenAI geçersiz JSON yanıtı')}
  if(Number(res.status)<200||Number(res.status)>=300)throw new Error(openAIErrorMessage(Number(res.status),obj,requestId));
  return {parsed:extractOpenAIOutput(obj),response:obj,requestId,started};
}
async function openAIHealthCheck(){
  if(!globalThis.AurumNativeAI?.configured?.())throw new Error('OpenAI API anahtarı Android güvenli alanında kayıtlı değil');
  const model=normalizedOpenAIModel(state.settings.openaiModel),res=await globalThis.AurumNativeAI.request('/v1/models','GET',null,30000),requestId=res.requestId||'';let obj={};
  try{obj=res.body?JSON.parse(res.body):{}}catch{throw new Error('OpenAI model listesi JSON değil')}
  if(Number(res.status)<200||Number(res.status)>=300)throw new Error(openAIErrorMessage(Number(res.status),obj,requestId));
  const ids=Array.isArray(obj.data)?obj.data.map(x=>String(x?.id||'')).filter(Boolean):[];
  let selected=model,migrated=false;
  if(!ids.includes(selected)){
    const preferred=['gpt-5.6-luna','gpt-5.6-terra','gpt-5.6','gpt-5.6-sol','gpt-5-mini','gpt-5','gpt-4.1-mini','gpt-4.1','gpt-4o-mini','gpt-4o'];
    const fallback=preferred.find(x=>ids.includes(x))
      ||ids.find(x=>/^gpt-5(?:[.-]|$)/.test(x))
      ||ids.find(x=>/^gpt-4\.1(?:-|$)/.test(x))
      ||ids.find(x=>/^gpt-4o(?:-|$)/.test(x));
    if(fallback){selected=fallback;migrated=selected!==model}
    else throw new Error('Bu OpenAI API projesinde Aurum ile uyumlu erişilebilir bir GPT modeli görünmüyor');
  }
  state.settings.openaiModel=selected;
  if(migrated)await saveSettings();
  return {ok:true,model:selected,modelVisible:true,modelMigrated:migrated,checkedAt:nowISO(),requestId};
}

const AI_AUDIT_SCHEMA={type:'object',additionalProperties:false,required:['executive_summary','confidence','diagnosis','missed_patterns','false_positive_patterns'],properties:{executive_summary:{type:'string'},confidence:{type:'number',minimum:0,maximum:1},diagnosis:{type:'array',items:{type:'object',additionalProperties:false,required:['title','evidence','severity'],properties:{title:{type:'string'},evidence:{type:'string'},severity:{type:'string',enum:['LOW','MEDIUM','HIGH','CRITICAL']}}}},missed_patterns:{type:'array',items:{type:'object',additionalProperties:false,required:['pattern','evidence','affected_symbols'],properties:{pattern:{type:'string'},evidence:{type:'string'},affected_symbols:{type:'array',items:{type:'string'}}}}},false_positive_patterns:{type:'array',items:{type:'object',additionalProperties:false,required:['pattern','evidence'],properties:{pattern:{type:'string'},evidence:{type:'string'}}}}}};

const AI_CANDIDATE_SCHEMA={type:'object',additionalProperties:false,required:['hypothesis','rationale','proposed_weights','risks','confidence'],properties:{hypothesis:{type:'string'},rationale:{type:'string'},proposed_weights:{type:'object',additionalProperties:false,required:['K1','K2','K3','K4','K5','K6','K7'],properties:{K1:{type:'number',minimum:0,maximum:1},K2:{type:'number',minimum:0,maximum:1},K3:{type:'number',minimum:0,maximum:1},K4:{type:'number',minimum:0,maximum:1},K5:{type:'number',minimum:0,maximum:1},K6:{type:'number',minimum:0,maximum:1},K7:{type:'number',minimum:0,maximum:1}}},risks:{type:'array',items:{type:'string'}},confidence:{type:'number',minimum:0,maximum:1}}};

function compactRunForAI(r){return {id:r.id,created_at:r.createdAt,evaluated_at:r.evaluatedAt,signal_date:r.signalTradingDate,window:r.decisionWindow,regime:r.marketRegime,metrics:r.metrics?{dual_precision:r.metrics.precisionDual20,top20_precision:r.metrics.precisionTop20,five_precision:r.metrics.precisionFivePct,dual_lift:r.metrics.dualLift,brier:r.metrics.brier,avg_max_net:r.metrics.avgMaxNetReturn,false_positive_rate:r.metrics.falsePositiveRate}:null,selected:(r.selection||[]).slice(0,20).map(x=>x.sym),actual_dual:(r.actualDual||[]).map(x=>x.sym),missed_dual:(r.actualDual||[]).map(x=>x.sym).filter(sym=>!(r.selection||[]).some(s=>s.sym===sym))};}

function buildAISnapshot(){const latest=latestTargetRun(),lm=learningMomentum(),criteria={};for(const k of MODEL_CRITERIA){const p=state.performance.raw?.[k]||{};criteria[k]={name:CRITERION_CATALOG[k]?.name,weight:state.performance.weights?.[k]??BASE_WEIGHTS[k],status:p.status||'ADAY',score:p.score??null,dual_precision:p.dualPrecision??null,dual_lift:p.dualLift??null,false_positive_rate:p.falsePositiveRate??null,predictions:p.predictions||0,independent_periods:p.independentPeriods||0};}return {generated_at:nowISO(),app_version:VERSION,model_version:MODEL_VERSION,target_definition:TARGET_DEFINITION,target_return_pct:state.settings.targetReturnPct,market_context:marketContext(new Date(),state.records.map(x=>x.latestDate).filter(Boolean).sort().at(-1)||null),data_quality:{records:state.records.length,mean_quality:mean(state.records.map(x=>x.quality)),behavior_coverage:state.behaviorMemory.coverage||0,genome_coverage:state.behaviorMemory.genomeCoverage||0,last_successful_sync:state.lastSuccessfulSync},learning:{score:lm.score,periods:lm.periods,last7:lm.last7,previous7:lm.previous7,delta:lm.delta,lift:lm.lift,brier:lm.brier,last_decision:state.performance.lastDecision,observations:state.performance.observations||0},current_weights:{...(state.performance.championWeights||state.performance.weights||BASE_WEIGHTS)},criteria,selection:state.selection.slice(0,20).map((x,i)=>({rank:i+1,sym:x.sym,total_score:x.totalScore,target_probability:x.targetProbability,day_change:x.dayChange,quality:x.quality,risk:x.riskLevel,regime:x.marketRegime,behavior_score:x.behaviorScore,genome_score:x.genomeScore,estimated_cost_pct:x.estimatedCostPct,supporting_criteria:x.supportingCriteria,target_reasons:x.targetReasons,warnings:x.warnings})),recent_runs:effectiveLearningRuns().slice(0,state.settings.aiMaxRecentRuns||30).map(compactRunForAI),latest_evaluated_run:latest?compactRunForAI(latest):null};}

async function aiCheckHealth(){if(!aiConfigured())throw new Error('OpenAI yapılandırılmadı');state.ai.busy=true;state.ai.lastError=null;render();try{const result=await openAIHealthCheck();state.ai.health=result;await log('ok','OpenAI bağlantısı doğrulandı',{model:result.model,requestId:result.requestId});showAurumNotice(result.modelMigrated?`OpenAI bağlantısı doğrulandı · model ${result.model} olarak güncellendi`:`OpenAI bağlantısı doğrulandı · ${result.model}`);return result;}catch(e){state.ai.lastError=e.message;await log('error','OpenAI bağlantı hatası',{error:e.message});throw e;}finally{state.ai.busy=false;render();}}

async function aiRunDailyAudit({manual=false}={}){
  if(state.ai.busy)return;if(!aiConfigured())throw new Error('OpenAI yapılandırılmadı');
  const aiEvidence=await reserveAICall('DAILY_AUDIT',manual);state.ai.busy=true;state.ai.lastError=null;render();
  try{
    const result=await openAIRequest({schemaName:'aurum_daily_audit',schema:AI_AUDIT_SCHEMA,instructions:'Aurum BIST karar destek sistemini denetle. Yalnız verilen kanıtı kullan. Finansal kesinlik iddiasında bulunma. Riskleri açıkça ayır. Çıktıyı Türkçe üret.',input:{snapshot:buildAISnapshot()}});
    const previous=state.ai.audits[0]?.record_hash||'',base={...result.parsed,id:uid(),created_at:nowISO(),previous_hash:previous,model:result.response?.model||state.settings.openaiModel,response_id:result.response?.id||null,request_id:result.requestId,usage:result.response?.usage||null,model_schema_fingerprint:MODEL_SCHEMA_FINGERPRINT};
    base.record_hash=await sha256Hex(JSON.stringify(deepSecretSanitize(base)));await dbPut('aiAudits',base);state.ai.audits.unshift(base);state.ai.audits=state.ai.audits.slice(0,100);state.ai.lastAudit=base;
    await markAIEvidenceResult('COMPLETED',{responseId:base.response_id,requestId:base.request_id});await log('ok','AI günlük denetimi tamamlandı',{audit:base.id,confidence:base.confidence,requestId:base.request_id,record_hash:base.record_hash,evidence:aiEvidence});showAurumNotice('AI denetimi tamamlandı');return base;
  }catch(e){await markAIEvidenceResult('FAILED',{errorClass:e?.name||'Error'});state.ai.lastError=e.message;await log('error','AI günlük denetimi başarısız',{error:e.message});throw e;}finally{state.ai.busy=false;render();}
}

async function maybeRunAIDailyAudit(){if(!state.settings.aiAutoDaily||!aiConfigured()||!state.runs.some(r=>r.evaluated))return null;const t=trParts();if(bistCalendarStatus(t.date)==='CLOSED'||t.hour<Number(state.settings.aiDailyHour||19))return null;if(state.ai.lastAudit&&ymd(state.ai.lastAudit.created_at)===t.date)return state.ai.lastAudit;return aiRunDailyAudit({manual:false});}

async function recordAIImpact(event){
  const row={id:event?.id||uid(),created_at:event?.created_at||nowISO(),snapshot:event?.snapshot||((await dbGet('meta','activeDataSnapshot'))?.value?.snapshotId||null),...deepSecretSanitize(event)};
  await dbPut('aiEvents',row);state.ai.events=[row,...(state.ai.events||[]).filter(x=>x.id!==row.id)].slice(0,200);return row;
}
function aiImpactReport(){const rows=(state.ai.events||[]).slice(0,40);return `<div class="section-head"><div class="section-title"><h2>AI / Öğrenme Etki Raporu</h2></div><small>Öneri ile canlı etki ayrıdır</small></div><div class="card aurum-ai-impact">${rows.length?rows.map(e=>`<div class="aurum-impact-row"><div><b>${html(e.change||e.type||'Model olayı')}</b><small>${html(e.criterion||'—')} · ${html(e.reason||'')}</small></div><div><span>${html(e.previous==null?'—':String(e.previous))} → ${html(e.next==null?'—':String(e.next))}</span><small>${html(e.outcome||'KAYIT')} · ${html(formatTableTime(e.created_at))}${e.snapshot?` · ${html(String(e.snapshot).slice(0,18))}`:''}</small></div></div>`).join(''):'<p class="muted">Henüz raporlanmış gerçek AI/öğrenme etkisi veya aday kararı yok.</p>'}</div>`;}

async function aiGenerateCandidate(){
  if(!state.settings.aiAllowCandidates)throw new Error('AI aday modeli ayarlardan kapalı');if(state.ai.busy)return;
  const audit=state.ai.lastAudit;if(!audit)throw new Error('Önce günlük AI denetimi çalıştırılmalı');
  const confidence=Number(audit.confidence||0),critical=(audit.diagnosis||[]).some(x=>['CRITICAL','HIGH'].includes(x.severity));
  if(confidence<Number(state.settings.aiMinAuditConfidenceForCandidate||.45)||critical)throw new Error(`Aday üretimi engellendi: denetim güveni/riski yeterli değil (${fmt(confidence*100,0)}%)`);
  const aiEvidence=await reserveAICall('CANDIDATE_GENERATE',true);state.ai.busy=true;state.ai.lastError=null;render();
  try{
    const evidence=effectiveLearningRuns(),result=await openAIRequest({schemaName:'aurum_candidate_model',schema:AI_CANDIDATE_SCHEMA,instructions:'Verilen Aurum denetim ve performans kanıtından yalnız kontrollü bir aday ağırlık önerisi üret. K10 bağımsız ağırlık değildir. Ağırlıkları 0 ile 1 arasında ver. Canlı modeli etkinleştirme kararı verme.',input:{snapshot:buildAISnapshot(),audit:deepSecretSanitize(audit)}}),cutoff=nowISO();
    const stored={...result.parsed,id:uid(),created_at:cutoff,status:'PENDING_FORWARD',response_id:result.response?.id||null,request_id:result.requestId,usage:result.response?.usage||null,evidence_cutoff_created_at:cutoff,evidence_cutoff_run_id:evidence[0]?.id||null,evidence_run_ids:evidence.map(x=>x.id),model_schema_fingerprint:MODEL_SCHEMA_FINGERPRINT,parameter_proposals_status:'REQUIRES_SEPARATE_VALIDATION'};
    await dbPut('aiCandidates',stored);await recordAIImpact({type:'AI_ADAY',change:'Aday model önerildi',previous:'Şampiyon model',next:stored.id,criterion:Object.keys(stored.proposed_weights||{}).join(', ')||'Ağırlıklar',reason:stored.rationale||stored.hypothesis||'AI aday önerisi',evidence:stored.evidence_run_ids||[],outcome:'ÖNERİ · CANLIYA UYGULANMADI'});state.ai.candidates.unshift(stored);state.ai.candidates=state.ai.candidates.slice(0,100);state.ai.lastCandidate=stored;await markAIEvidenceResult('COMPLETED',{responseId:stored.response_id,requestId:stored.request_id});await log('ok','AI adayı yalnız ileri dönem doğrulamasına alındı',{candidate:stored.id,cutoff,requestId:stored.request_id,evidence:aiEvidence});showAurumNotice('Aday model oluşturuldu');return stored;
  }catch(e){await markAIEvidenceResult('FAILED',{errorClass:e?.name||'Error'});state.ai.lastError=e.message;await log('error','AI aday modeli oluşturulamadı',{error:e.message});throw e;}finally{state.ai.busy=false;render();}
}

async function aiValidateCandidate(id){
  const cand=state.ai.candidates.find(x=>x.id===id);if(!cand)throw new Error('Aday bulunamadı');
  const cutoff=new Date(cand.evidence_cutoff_created_at||cand.created_at||0).getTime(),minN=Math.max(Number(state.settings.aiMinValidationPeriods||60),Number(state.settings.minWeightObservations||60));
  const runs=effectiveLearningRuns().filter(x=>new Date(x.createdAt).getTime()>cutoff&&x.evaluated&&x.modelSchemaFingerprint===MODEL_SCHEMA_FINGERPRINT).sort((a,b)=>a.createdAt.localeCompare(b.createdAt));
  let validation;
  if(runs.length<minN){validation={status:'PENDING_FORWARD',reason:`Adaydan sonra ${minN} yeni bağımsız dönem gerekir`,periods:runs.length,remaining:minN-runs.length,cutoff:cand.evidence_cutoff_created_at};cand.status='PENDING_FORWARD';}
  else{const holdout=runs.slice(0,minN),current=normalizeWeights(state.performance.championWeights||state.performance.weights||BASE_WEIGHTS),proposed=normalizeWeights({...current,...(cand.proposed_weights||{})}),champ=validationScore(holdout,current),candidate=validationScore(holdout,proposed),paired=pairedPromotionEvidence(holdout,current,proposed),margin=Number(state.settings.promotionMargin||.35),passed=Number.isFinite(candidate.score)&&candidate.score>=(champ.score??-Infinity)+margin&&(candidate.utility??-Infinity)>=(champ.utility??-Infinity)&&(candidate.avgClose??-Infinity)>=(champ.avgClose??-Infinity)-.05&&(candidate.alpha??-Infinity)>=(champ.alpha??-Infinity)&&(candidate.precision??0)>=(champ.precision??0)-.01&&(candidate.lossRate??1)<=(champ.lossRate??1)+.02&&paired.n>=Math.max(30,Math.floor(minN/2))&&(paired.lower90??-Infinity)>=0;
    validation={status:passed?'PASSED':'FAILED',periods:holdout.length,validation_run_ids:holdout.map(x=>x.id),champion:champ,candidate,pairedEvidence:paired,required_margin:margin,validated_at:nowISO(),future_only:true};cand.status=validation.status;}
  cand.validation=validation;await dbPut('aiCandidates',cand);await recordAIImpact({type:'AI_DOĞRULAMA',change:'Aday ileri dönem doğrulaması',previous:'PENDING_FORWARD',next:validation.status,criterion:'Model adayı',reason:validation.reason||`Şampiyon ${validation.champion?.score??'—'} / Aday ${validation.candidate?.score??'—'}`,evidence:validation.validation_run_ids||[],outcome:validation.status==='PASSED'?'KABUL ADAYI · HENÜZ CANLI DEĞİL':validation.status==='FAILED'?'REDDEDİLDİ':'BEKLEME'});state.ai.lastCandidate=cand;await log(validation.status==='PASSED'?'ok':'info','AI aday ileri dönem doğrulaması',{candidate:id,status:validation.status,periods:validation.periods});render();showAurumNotice(validation.status==='PASSED'?'Doğrulama tamamlandı · Başarılı':validation.status==='FAILED'?'Doğrulama tamamlandı · Başarısız':'Doğrulama güncellendi');return validation;
}

async function aiPromoteCandidate(id){
  const cand=state.ai.candidates.find(x=>x.id===id);if(!cand||cand.validation?.status!=='PASSED'||cand.validation?.future_only!==true)throw new Error('Yalnız gerçek ileri dönem doğrulamasını geçen aday etkinleştirilebilir');
  if(!confirm('Doğrulanmış aday ağırlıkları günlük değişim sınırıyla etkinleştirilsin mi?'))return;
  const old=normalizeWeights(state.performance.championWeights||state.performance.weights||BASE_WEIGHTS),target=normalizeWeights({...old,...(cand.proposed_weights||{})}),next=projectWeights(target,old,state.performance.raw||{},Number(state.settings.weightDailyCapPct||1)/100);
  for(const k of MODEL_CRITERIA){const a=Number(old[k]),b=Number(next[k]);if(Number.isFinite(a)&&Number.isFinite(b)&&Math.abs(a-b)>1e-12)await recordAIImpact({type:'AI_CANLI_ETKİ',change:'Kriter ağırlığı değişti',previous:a,next:b,delta:b-a,criterion:k,reason:cand.rationale||cand.hypothesis||'İleri dönem doğrulamasını geçen aday kullanıcı onayıyla etkinleştirildi',evidence:cand.validation?.validation_run_ids||[],outcome:'UYGULANDI'});}state.performance.weights=next;state.performance.championWeights=next;state.performance.lastDecision='AI_MANUEL_ONAY';state.performance.lastWeightUpdateDate=trParts().date;state.performance.history=[{date:trParts().date,decision:'AI_MANUEL_ONAY',candidateId:id,weights:{...next},validation:cand.validation},...(state.performance.history||[])].slice(0,180);
  cand.status='PROMOTED';cand.promoted_at=nowISO();await dbPut('aiCandidates',cand);await dbPut('meta',{key:'performance',value:state.performance,updatedAt:nowISO()});if(state.records.length){const built=rebuildModelViews(globalThis.calculationRecords?.()||state.records.filter(isTruthEligible));state.scores=built.scores;state.selection=built.selection;state.modelBySym=built.bySym;await updateSelectionLifecycle();}await log('ok','AI aday ağırlıkları manuel onayla etkinleştirildi',{candidate:id,weights:next});render();showAurumNotice('Aday model etkinleştirildi');
}

async function aiRejectCandidate(id){const cand=state.ai.candidates.find(x=>x.id===id);if(!cand)return;cand.status='REJECTED';cand.rejected_at=nowISO();await dbPut('aiCandidates',cand);await recordAIImpact({type:'AI_ADAY',change:'Aday model kararı',previous:cand.validation?.status||'ADAY',next:'REJECTED',criterion:'Model adayı',reason:'Kullanıcı tarafından reddedildi',outcome:'REDDEDİLDİ'});await log('info','AI adayı reddedildi',{candidate:id});render();showAurumNotice('Aday model reddedildi');}

window.saveAISettings=async()=>{try{
  const enabled=$('#aiEnabled')?.value==='true',keyInput=$('#openaiApiKey')||$('#generalOpenaiApiKey'),typed=String(keyInput?.value||'').trim(),key=typed?normalizeOpenAIKey(typed):'',stored=!!globalThis.AurumNativeAI?.configured?.(),model=normalizedOpenAIModel($('#openaiModel')?.value||state.settings.openaiModel||OPENAI_DEFAULT_MODEL);
  if(typed&&!key)throw new Error('OpenAI API anahtarı geçersiz');
  if(key&&!globalThis.AurumNativeAI?.save?.(key))throw new Error('API anahtarı Android güvenli alanına kaydedilemedi');
  if(enabled&&!key&&!stored&&!globalThis.AurumNativeAI?.configured?.())throw new Error('OpenAI API anahtarı gerekli');
  if(!model)throw new Error('OpenAI modeli boş olamaz');
  state.settings.aiEnabled=enabled;state.settings.openaiApiKey='';state.settings.openaiModel=model;
  state.settings.openaiMaxOutputTokens=clamp(Number($('#openaiMaxOutputTokens')?.value||8000),512,16000);
  state.settings.openaiReasoningEffort=$('#openaiReasoningEffort')?.value??state.settings.openaiReasoningEffort;
  state.settings.aiAutoDaily=$('#aiAutoDaily')?.value==='true';state.settings.aiDailyHour=clamp(Number($('#aiDailyHour')?.value||19),0,23);
  state.settings.aiAllowCandidates=$('#aiAllowCandidates')?.value==='true';state.settings.aiAutoPromoteValidated=false;
  state.settings.aiMinValidationPeriods=clamp(Number($('#aiMinValidationPeriods')?.value||60),40,240);
  state.settings.aiMaxRecentRuns=clamp(Number($('#aiMaxRecentRuns')?.value||state.settings.aiMaxRecentRuns||30),5,200);
  state.settings.aiDailyCallLimit=clamp(Number($('#aiDailyCallLimit')?.value||2),0,20);
  state.settings.aiRequireManualPaidCall=$('#aiRequireManualPaidCall')?$('#aiRequireManualPaidCall').value==='true':state.settings.aiRequireManualPaidCall!==false;
  state.settings.aiRequireNewMarketBucket=$('#aiRequireNewMarketBucket')?$('#aiRequireNewMarketBucket').value==='true':state.settings.aiRequireNewMarketBucket!==false;
  if($('#aiMarketTimeBuckets')){const buckets=String($('#aiMarketTimeBuckets').value||'').split(/[;,\s]+/).filter(Boolean);if(!buckets.length||buckets.some(x=>!/^([01]\d|2[0-3]):[0-5]\d$/.test(x)))throw new Error('AI piyasa zaman dilimleri HH:MM biçiminde olmalıdır');state.settings.aiMarketTimeBuckets=[...new Set(buckets)].sort().join(',');}
  state.settings.aiMinAuditConfidenceForCandidate=clamp(Number($('#aiMinAuditConfidenceForCandidate')?.value||.45),0,1);
  state.settings.settingsSchemaVersion=SETTINGS_SCHEMA_VERSION;delete state.settings.aiGatewayUrl;delete state.settings.aiGatewayToken;state.ai.lastError=null;
  await saveSettings();await log('ok','OpenAI/AI ayarları kaydedildi',{enabled,model,keyUpdated:!!key,autoPromote:false,autoDaily:state.settings.aiAutoDaily});render();showAurumNotice('API ve AI ayarları kaydedildi','success',2600);
}catch(e){state.ai.lastError=e.message;await log('error','OpenAI/AI ayarları kaydedilemedi',{error:e.message});render();showAurumNotice(e?.message||'API ve AI ayarları kaydedilemedi','error',4200);}};


async function runAIUIAction(action,label){
  try{return await action();}
  catch(e){
    const message=e?.message||String(e||'Bilinmeyen hata');
    state.ai.lastError=message;
    try{await log('error',`${label} başarısız`,{error:message});}catch{}
    render();
    showAurumNotice(message,'error',5000);
    return null;
  }
}

