function aiAuditCard(a){if(!a)return `<div class="card notice">Henüz AI denetimi yok. OpenAI anahtarını kaydedip “Günlük Denetimi Çalıştır” düğmesini kullanın.</div>`;return `<div class="card gold-edge"><div class="list-row"><div><strong>${html(a.executive_summary||'AI Denetimi')}</strong><small>${new Date(a.created_at).toLocaleString('tr-TR')} · ${html(a.model||'')}</small></div><span class="badge ${Number(a.confidence)>=.7?'ok':'warn'}">GÜVEN ${fmt(Number(a.confidence||0)*100,0)}%</span></div><h3>Tanılar</h3><div class="list">${(a.diagnosis||[]).map(x=>`<div class="list-row"><div><b>${html(x.title)}</b><small>${html(x.evidence)}</small></div><span class="badge ${x.severity==='CRITICAL'||x.severity==='HIGH'?'bad':x.severity==='MEDIUM'?'warn':'ok'}">${html(x.severity)}</span></div>`).join('')||'<p class="muted">Yok</p>'}</div><h3>Kaçırılan örüntüler</h3>${(a.missed_patterns||[]).map(x=>`<div class="ai-finding"><b>${html(x.pattern)}</b><p>${html(x.evidence)}</p><small>${html((x.affected_symbols||[]).join(', '))}</small></div>`).join('')||'<p class="muted">Yok</p>'}<h3>Yanlış pozitif örüntüleri</h3>${(a.false_positive_patterns||[]).map(x=>`<div class="ai-finding"><b>${html(x.pattern)}</b><p>${html(x.evidence)}</p></div>`).join('')||'<p class="muted">Yok</p>'}</div>`;}

function aiCandidateCard(c){const v=c.validation||{},pending=v.status==='PENDING_FORWARD';return `<div class="card"><div class="list-row"><div><strong>${html(c.hypothesis||c.id)}</strong><small>${new Date(c.created_at).toLocaleString('tr-TR')} · ${html(c.rationale||'')}</small></div><span class="badge ${c.status==='PASSED'||c.status==='PROMOTED'?'ok':c.status==='FAILED'||c.status==='REJECTED'?'bad':'warn'}">${html(c.status||'PENDING_FORWARD')}</span></div><div class="weight-grid">${MODEL_CRITERIA.map(k=>`<div><small>${k}</small><b>${fmt(Number(c.proposed_weights?.[k]||0)*100,1)}%</b></div>`).join('')}</div>${v.status?`<div class="notice">${pending?`${v.remaining||0} yeni bağımsız dönem daha gerekli`:`Doğrulama ${html(v.status)} · Şampiyon ${fmt(v.champion?.score,2)} · Aday ${fmt(v.candidate?.score,2)}`} · ${v.periods||0} dönem</div>`:''}<div class="actions"><button class="ghost-btn" onclick="aiValidateCandidateUI('${c.id}')">Yeni Dönemleri Kontrol Et</button>${v.status==='PASSED'&&c.status!=='PROMOTED'?`<button class="gold-btn" onclick="aiPromoteCandidateUI('${c.id}')">Manuel Etkinleştir</button>`:''}<button class="danger-btn" onclick="aiRejectCandidateUI('${c.id}')">Reddet</button></div></div>`;}

function aiPage(){const h=state.ai.health,a=state.ai.lastAudit,cands=state.ai.candidates.slice(0,10),configured=aiConfigured(),used=state.usage?.[trParts().date]?.count||0,limit=Number(state.settings.aiDailyCallLimit||2);return `<div class="grid metrics">${metric('OpenAI',configured?(h?.ok?'BAĞLI':'YAPILANDIRILDI'):'KAPALI',h?.model||state.settings.openaiModel||OPENAI_DEFAULT_MODEL,h?.ok?'green':'gold')}${metric('Günlük kullanım',`${used}/${limit}`,`Kalan ${Math.max(0,limit-used)}`)}${metric('Son denetim',a?new Date(a.created_at).toLocaleDateString('tr-TR'):'—',a?.id||'Henüz yok')}${metric('Aday model',state.ai.lastCandidate?.status||'—',state.ai.lastCandidate?.id||'Henüz yok')}${metric('Yönetim','MANUEL ONAY','Future-only doğrulama')}</div><div class="section-head"><div class="section-title"><h2>OpenAI Ayarları</h2></div><small>Haricî gateway yok</small></div><div class="card form-grid"><div class="field"><label>AI bağlantısı</label><select id="aiEnabled"><option value="true" ${state.settings.aiEnabled?'selected':''}>Aktif</option><option value="false" ${!state.settings.aiEnabled?'selected':''}>Kapalı</option></select></div><div class="field"><label>Model</label><input id="openaiModel" value="${html(state.settings.openaiModel||OPENAI_DEFAULT_MODEL)}" autocomplete="off"></div><div class="field" style="grid-column:1/-1"><label>OpenAI API Anahtarı</label><button class="ghost-btn" type="button" onclick="goPage('settings')">API / AI Ayarları</button></div><div class="field"><label>Azami çıktı tokenı</label><input id="openaiMaxOutputTokens" type="number" min="512" max="16000" value="${state.settings.openaiMaxOutputTokens||8000}"></div><div class="field"><label>Muhakeme düzeyi</label><select id="openaiReasoningEffort"><option value="low" ${state.settings.openaiReasoningEffort==='low'?'selected':''}>Düşük</option><option value="medium" ${state.settings.openaiReasoningEffort==='medium'?'selected':''}>Orta</option><option value="" ${!state.settings.openaiReasoningEffort?'selected':''}>Gönderme</option></select></div><div class="field"><label>Günlük otomatik denetim</label><select id="aiAutoDaily"><option value="true" ${state.settings.aiAutoDaily?'selected':''}>Aktif</option><option value="false" ${!state.settings.aiAutoDaily?'selected':''}>Kapalı</option></select></div><div class="field"><label>Denetim saati</label><input id="aiDailyHour" type="number" min="18" max="23" value="${state.settings.aiDailyHour||19}"></div><div class="field"><label>Aday model üretimi</label><select id="aiAllowCandidates"><option value="true" ${state.settings.aiAllowCandidates?'selected':''}>Aktif</option><option value="false" ${!state.settings.aiAllowCandidates?'selected':''}>Kapalı</option></select></div><div class="field"><label>Asgari bağımsız doğrulama dönemi</label><input id="aiMinValidationPeriods" type="number" min="12" max="180" value="${state.settings.aiMinValidationPeriods||20}"></div><div class="field"><label>Günlük azami ücretli AI çağrısı</label><input id="aiDailyCallLimit" type="number" min="0" max="20" value="${state.settings.aiDailyCallLimit||2}"></div><div class="field"><label>Aday için asgari denetim güveni</label><input id="aiMinAuditConfidenceForCandidate" type="number" min="0" max="1" step="0.05" value="${state.settings.aiMinAuditConfidenceForCandidate||.45}"></div><div class="actions" style="grid-column:1/-1"><button class="gold-btn" onclick="saveAISettings()">Ayarları Kaydet</button><button class="ghost-btn" onclick="aiCheckHealthUI()" ${state.ai.busy?'disabled':''}>Bağlantıyı Test Et</button><button class="ghost-btn" onclick="aiRunDailyAuditUI()" ${state.ai.busy||!configured?'disabled':''}>Günlük Denetimi Çalıştır</button><button class="ghost-btn" onclick="aiGenerateCandidateUI()" ${state.ai.busy||!configured||!a?'disabled':''}>Aday Model Üret</button></div>${state.ai.lastError?`<p class="error-text" style="grid-column:1/-1">${html(state.ai.lastError)}</p>`:''}</div><div class="section-head"><div class="section-title"><h2>Son AI Denetimi</h2></div><small>Yapılandırılmış · hash zincirli kayıt</small></div>${aiAuditCard(a)}<div class="section-head"><div class="section-title"><h2>Aday Modeller</h2></div><small>Doğrudan canlıya alınmaz</small></div><div class="grid">${cands.map(aiCandidateCard).join('')||'<div class="card notice">Aday model yok.</div>'}</div>${aiImpactReport()}<div class="section-head"><h2>Yönetim</h2></div><div class="card notice aurum-brief-notice">Adaylar doğrulama ve kullanıcı onayı olmadan etkinleşmez.</div>`;}


