function aurumKHistoryExportRows(){
  let rs=[];try{rs=globalThis.AurumKnHistoryV117?.rows?.()||kh117Rows()||[]}catch{rs=[]}
  const out=[];
  for(const r of rs){
    const label=String(r?._label||''),knDate=String(r?.date||''),reelDate=String(r?.reelDate||r?._reelDate||r?.date||'');
    const trendRank=new Map((r?.trend||[]).map((x,i)=>[String(x?.k||''),i+1]));
    (r?.reelTop20||[]).slice(0,20).forEach((x,i)=>out.push({T:label,KnDate:knDate,ReelDate:reelDate,Section:'REEL_TOPN',Criterion:'REEL_TOPN',Rank:i+1,Symbol:x?.sym||'',ReelReturnPct:x?.ret??x?.dayReturn??x?.realReturn??null,KnReturnPct:null,Hit:null,HitCount:null,Total:20,TrendRank:null}));
    for(const k of (globalThis.KN_V117_ORDER||['K1','K2','K3','K4','K5','K6','K7','K8','K9','K10','K11','K12'])){
      const a=(r?.criteria?.[k]||[]).slice(0,20),ss=r?.summaries?.[k]||{};
      a.forEach((x,i)=>out.push({T:label,KnDate:knDate,ReelDate:reelDate,Section:'KN_TOPN',Criterion:k,Rank:i+1,Symbol:x?.sym||'',ReelReturnPct:x?.dayReturn??x?.ret??x?.realReturn??null,KnReturnPct:x?.knReturn??x?.returnAvg??x?.avgReturn??null,Hit:!!x?.realHit,HitCount:ss?.hitCount??null,Total:ss?.total??a.length,ReelAveragePct:ss?.realAvg??null,KnAveragePct:ss?.knAvg??null,TrendRank:trendRank.get(k)??null}));
    }
  }
  return out;
}
async function aurumExportRows(key){
  if(/^K(?:[1-9]|1[0-2])$/.test(key))return (state.scores?.[key]||[]).map((x,i)=>aurumExportSafe({rank:i+1,symbol:x.sym,score:x.score,latestDate:x.record?.latestDate,price:x.record?.livePrice,dayChange:x.record?.dayChange,quality:x.record?.quality,targetProbability:state.modelBySym?.get?.(x.sym)?.targetProbability??null}));
  if(key==='selection')return aurumExportSafe((state.selection||[]).map((x,i)=>({rank:i+1,...x})));
  if(key==='records')return aurumExportSafe(await dbAll('records'));
  if(key==='runs')return aurumExportSafe(aurumKHistoryExportRows());
  if(key==='settings')return [aurumExportSafe({...state.settings,openaiApiKey:''})];
  try{return aurumExportSafe(await dbAll(key))}catch{return []}
}
