function aurumRowsShape(rows){const arr=Array.isArray(rows)?rows:[rows],objects=arr.map(x=>x&&typeof x==='object'&&!Array.isArray(x)?x:{value:x}),keys=[];for(const o of objects)for(const k of Object.keys(o))if(!keys.includes(k))keys.push(k);return {keys,rows:objects}}

