  if(/^K(?:[1-9]|1[0-2])$/.test(key)){
    const rows=(state.scores?.[key]||[]).slice(0,Math.max(20,Number(state.settings?.topN||20)));
    return {...t,rows:rows.map((x,i)=>{const r=x.record||state.recordMap?.get?.(x.sym)||{},m=state.modelBySym?.get?.(x.sym)||{};return {'#':i+1,'Hisse':x.sym,'Veri Zamanı':marketTime(r),'Anlık Değişim (%)':pctx(r.dayChange),'Anlık':two(r.livePrice),'Hacim x':two(r.volumeBreakout),'ATR%':two(r.atrPct),'KnzTOP20':(globalThis.KN_V117_ORDER||[]).filter(k=>(state.scores?.[k]||[]).slice(0,20).some(z=>z.sym===x.sym)).join(' · ')||'—','Skor':two(x.score),'Hedef Olasılığı':Number.isFinite(m.targetProbability)?pctx(m.targetProbability*100):'—','Kapanış Tarihi':r.latestDate||'—','Kaynak':r.source||'—'};})};
  }
