  if(key==='runs'){
    let rs=[];try{rs=globalThis.AurumKnHistoryV117?.rows?.()||[]}catch{}
    const order=globalThis.KN_V117_ORDER||['K1','K2','K3','K4','K5','K6','K7','K8','K9','K10','K11','K12'];
    const seat=new Set(globalThis.KN_V117_SEAT_ORDER||['K1','K2','K3','K4','K5','K6','K7']);
    return {...t,rows:rs.map(r=>{const o={'Gün':`${r?._label||'—'}\n${r?.date||'—'} · ${r?._t0?'CANLI':'KESİN'}`};const tr=(r?.trend||[]).filter(x=>seat.has(String(x?.k||'')));o['KN_TREND']=tr.map(x=>`${x.k}: ${Number(x.hitCount||0)}/${Number(x.total||20)}`).join('\n')+`\n${marketTime(r)}`;const reel=(r?.reelTop20||[]).slice(0,20);o['REEL TOPN']=reel.map(x=>`${x.sym} (${pctx(x.ret??x.dayReturn??x.realReturn)})`).join('\n')+`\nReel tarihi: ${r?.reelDate||r?._reelDate||r?.date||'—'}\n${marketTime(r)}`;for(const k of order){const a=(r?.criteria?.[k]||[]).slice(0,20),sm=r?.summaries?.[k]||{};o[`${k} TOPN`]=a.map(x=>`${x.sym} (${pctx(x.dayReturn??x.ret??x.realReturn)} | ${seat.has(k)?pctx(x.knReturn??x.returnAvg??x.avgReturn):'ANALİZ'})${x.realHit?' ✓':''}`).join('\n')+`\n${seat.has(k)?`İsabet: ${Number(sm.hitCount||0)}/${a.length||20} · Reel Ort: ${pctx(sm.realAvg)}\nKn Ort: ${pctx(sm.knAvg)}`:'Analiz/meta tablo'}\n${marketTime(r)}`;}return o;})};
  }
