function aurumPdf(tables){const lines=[];for(const t of tables){lines.push(`=== ${aurumAscii(t.label)} ===`);const {keys,rows}=aurumRowsShape(t.rows);lines.push(keys.join(' | ').slice(0,110));for(const r of rows.slice(0,3000))lines.push(keys.map(k=>aurumAscii(aurumFlatCell(r[k])).replace(/\s+/g,' ').slice(0,32)).join(' | ').slice(0,110));lines.push('')}const pages=[];for(let i=0;i<lines.length;i+=48)pages.push(lines.slice(i,i+48));const objs=[null];const add=s=>(objs.push(String(s)),objs.length-1),font=add('<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>'),pageIds=[];for(const pg of pages.length?pages:[['Bos tablo']]){const content=['BT','/F1 7 Tf','40 800 Td'];for(let i=0;i<pg.length;i++){const text=aurumAscii(pg[i]).replace(/([\\()])/g,'\\$1');content.push(`(${text}) Tj`);if(i<pg.length-1)content.push('0 -15 Td')}content.push('ET');const stream=content.join('\n'),cid=add(`<< /Length ${aurumUtf8(stream).length} >>\nstream\n${stream}\nendstream`);pageIds.push(add(`__PAGE__${cid}`))}const pagesId=add('');for(let i=0;i<pageIds.length;i++){const cid=Number(objs[pageIds[i]].replace('__PAGE__',''));objs[pageIds[i]]=`<< /Type /Page /Parent ${pagesId} 0 R /MediaBox [0 0 595 842] /Resources << /Font << /F1 ${font} 0 R >> >> /Contents ${cid} 0 R >>`}objs[pagesId]=`<< /Type /Pages /Kids [${pageIds.map(id=>`${id} 0 R`).join(' ')}] /Count ${pageIds.length} >>`;const catalog=add(`<< /Type /Catalog /Pages ${pagesId} 0 R >>`);let body='%PDF-1.4\n',offsets=[0];for(let i=1;i<objs.length;i++){offsets[i]=aurumUtf8(body).length;body+=`${i} 0 obj\n${objs[i]}\nendobj\n`}const xref=aurumUtf8(body).length;body+=`xref\n0 ${objs.length}\n0000000000 65535 f \n`;for(let i=1;i<objs.length;i++)body+=`${String(offsets[i]).padStart(10,'0')} 00000 n \n`;body+=`trailer\n<< /Size ${objs.length} /Root ${catalog} 0 R >>\nstartxref\n${xref}\n%%EOF`;return aurumUtf8(body)}
function aurumB64(bytes){let out='';for(let i=0;i<bytes.length;i+=0x6000)out+=String.fromCharCode(...bytes.subarray(i,i+0x6000));return btoa(out)}
function aurumNativePrompt(params,data=''){const q=new URLSearchParams(params);try{return window.prompt(`aurum://native?${q.toString()}`,data)||''}catch{return ''}}
function aurumFileSafe(s){return String(s||'tablo').replace(/[^A-Za-z0-9._-]+/g,'_').replace(/^_+|_+$/g,'').slice(0,90)||'tablo'}
async function aurumNativeSave(name,mime,encoding,data,target){const r=aurumNativePrompt({cmd:'export',target:target==='custom'?'custom':'downloads',name,mime,encoding},data);if(r==='OK')return true;if(r==='ERR:NO_FOLDER')throw new Error('Özel klasör seçilmemiş. Önce “Klasör Seç / Değiştir” düğmesini kullanın.');if(r==='ERR:ANDROID_10_REQUIRED')throw new Error('Doğrudan İndirilenler kaydı Android 10+ gerektiriyor; bu cihazda Özel klasör seçeneğini kullanın.');throw new Error(`Android kayıt işlemi başarısız: ${r||'yanıt yok'}`)}
async function aurumExportSelected(){const selected=[...document.querySelectorAll('[data-export-table]:checked')].map(x=>x.value);if(!selected.length)throw new Error('En az bir tablo seçin');const format=$('#aurumExportFormat')?.value||state.settings.exportFormat||'json',mode=$('#aurumExportMode')?.value||state.settings.exportMode||'separate',target=$('#aurumExportTarget')?.value||state.settings.exportTarget||'downloads';state.settings.exportTables=selected;state.settings.exportFormat=format;state.settings.exportMode=mode;state.settings.exportTarget=target;await saveSettings();const tables=[];for(const key of selected)tables.push({key,label:aurumExportLabel(key),rows:await aurumExportRows(key)});const stamp=trParts().date.replace(/-/g,'');let count=0;
  const saveOne=async(t)=>{const base=`aurum_${aurumFileSafe(t.key)}_${stamp}`;if(format==='json'){await aurumNativeSave(`${base}.json`,'application/json','utf8',JSON.stringify({table:t.key,label:t.label,exportedAt:nowISO(),rows:t.rows},null,2),target)}else if(format==='csv'){await aurumNativeSave(`${base}.csv`,'text/csv','utf8',aurumCSV(t.rows),target)}else if(format==='xlsx'){await aurumNativeSave(`${base}.xlsx`,'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet','base64',aurumB64(aurumXlsx([t])),target)}else {await aurumNativeSave(`${base}.pdf`,'application/pdf','base64',aurumB64(aurumPdf([t])),target)}count++};
  if(mode==='separate'||tables.length===1){for(const t of tables)await saveOne(t)}else{const base=`aurum_coklu_${stamp}`;if(format==='json'){const obj={version:VERSION,modelVersion:MODEL_VERSION,exportedAt:nowISO(),tables:Object.fromEntries(tables.map(t=>[t.key,t.rows]))};await aurumNativeSave(`${base}.json`,'application/json','utf8',JSON.stringify(obj,null,2),target)}else if(format==='xlsx'){await aurumNativeSave(`${base}.xlsx`,'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet','base64',aurumB64(aurumXlsx(tables)),target)}else if(format==='pdf'){await aurumNativeSave(`${base}.pdf`,'application/pdf','base64',aurumB64(aurumPdf(tables)),target)}else {const text=tables.map(t=>`# TABLE: ${t.label}\r\n${aurumCSV(t.rows).replace(/^\ufeff/,'')}`).join('\r\n\r\n');await aurumNativeSave(`${base}.csv`,'text/csv','utf8','\ufeff'+text,target)}count=1}
  await log('ok','Dışa aktarma tamamlandı',{tables:selected,format,mode,target,files:count});showAurumNotice(`${selected.length} tablo · ${count} dosya kaydedildi`,'success',3600);return true}
window.exportData=async()=>{try{return await aurumExportSelected()}catch(e){await log('error','Dışa aktarma başarısız',{error:e?.message||String(e)});showAurumNotice(e?.message||String(e),'error',5200);return false}};
window.aurumChooseExportFolder=async()=>{try{state.settings.exportTarget='custom';await saveSettings();const r=aurumNativePrompt({cmd:'folder_pick'},'');if(r!=='PICKING')throw new Error(`Klasör seçici açılamadı: ${r||'yanıt yok'}`);showAurumNotice('Klasörü seçin; izin kalıcı olarak saklanacak','info',3200);setTimeout(()=>window.refreshExportFolderStatus?.(),900);return true}catch(e){showAurumNotice(e?.message||String(e),'error',4200);return false}};
window.refreshExportFolderStatus=()=>{const el=document.getElementById('aurumExportFolderStatus');if(!el)return '';const uri=aurumNativePrompt({cmd:'folder_status'},'');el.textContent=uri?`Özel klasör hazır · ${decodeURIComponent(uri).slice(-90)}`:'Henüz özel klasör seçilmedi';el.className=`muted aurum-export-folder-status ${uri?'ready':''}`;return uri};
window.saveExportPreferences=async()=>{try{state.settings.exportTarget=$('#aurumExportTarget')?.value==='custom'?'custom':'downloads';state.settings.exportFormat=$('#aurumExportFormat')?.value||'json';state.settings.exportMode=$('#aurumExportMode')?.value||'separate';state.settings.exportTables=[...document.querySelectorAll('[data-export-table]:checked')].map(x=>x.value);if(!state.settings.exportTables.length)throw new Error('En az bir tablo seçin');await saveSettings();showAurumNotice('Dışa aktarma tercihleri kaydedildi','success',2200);return true}catch(e){showAurumNotice(e?.message||String(e),'error',3200);return false}};
window.addEventListener?.('focus',()=>setTimeout(()=>window.refreshExportFolderStatus?.(),250));document.addEventListener?.('visibilitychange',()=>{if(!document.hidden)setTimeout(()=>window.refreshExportFolderStatus?.(),250)});

